/* ═══════ js/components/search-select.js ═══════ */
// ================================================================
//  components/search-select.js — SearchSelect (v10)
//
//  PURPOSE: A searchable replacement for the <select> pickers in the
//  Estimates tab (Materials, Labor, Equipment).
//
//  WHY: a native <select> only jump-scrolls by first letter, so with a
//  few hundred approved catalog entries you are scrolling blind — and
//  "12mm rebar" is unfindable by typing "rebar". This matches on ANY
//  part of the name, brand, ID, category, or specification, groups the
//  results, and shows unit + DB rate on the right so you can confirm
//  the right item before committing.
//
//  Keyboard-first: type to filter, arrow to move, Enter to choose,
//  Escape to close. The committed value lives in a hidden input, so
//  existing save logic keeps reading a plain form field.
// ================================================================

const SearchSelect = {
    _reg: {},          // id -> { options, onSelect, cursor, filtered }

    /**
     * render(cfg) -> HTML string
     *   id, value, display, placeholder,
     *   options: [{ value, label, group, meta, keywords }],
     *   onSelect: function(value, option)   // real function, not a string
     */
    render(cfg) {
        const id = cfg.id;
        this._reg[id] = {
            options: cfg.options || [],
            onSelect: typeof cfg.onSelect === 'function' ? cfg.onSelect : null,
            cursor: -1,
            filtered: []
        };
        const disp = String(cfg.display || '').replace(/"/g, '&quot;');
        const ph = String(cfg.placeholder || 'Search...').replace(/"/g, '&quot;');
        const val = String(cfg.value == null ? '' : cfg.value).replace(/"/g, '&quot;');
        return `
            <div class="ss" data-ss="${id}">
                <input type="hidden" id="${id}-val" value="${val}" />
                <input type="text" class="ss-input" id="${id}" value="${disp}" placeholder="${ph}"
                    autocomplete="off" spellcheck="false"
                    oninput="SearchSelect.onInput('${id}')"
                    onfocus="SearchSelect.onFocus('${id}')"
                    onblur="SearchSelect.onBlur('${id}')"
                    onkeydown="SearchSelect.onKey('${id}', event)" />
                <span class="ss-caret">${Icon.search({ size: 13 })}</span>
                <div class="ss-list" id="${id}-list"></div>
            </div>`;
    },

    _match(opt, needle) {
        if (!needle) return true;
        const hay = [opt.label, opt.group, opt.meta, opt.value, opt.keywords]
            .filter(Boolean).join(' ').toLowerCase();
        // every term must appear somewhere, in any order: "rebar 12"
        // finds "Deformed Rebar 12mm x 6m"
        return needle.toLowerCase().split(/\s+/).filter(Boolean)
            .every(t => hay.indexOf(t) > -1);
    },

    _hl(text, needle) {
        const esc = String(text == null ? '' : text)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        const t = (needle || '').trim().split(/\s+/)[0];
        if (!t) return esc;
        const i = esc.toLowerCase().indexOf(t.toLowerCase());
        if (i < 0) return esc;
        return esc.slice(0, i) + '<mark>' + esc.slice(i, i + t.length) + '</mark>' + esc.slice(i + t.length);
    },

    _paint(id) {
        const st = this._reg[id];
        const inp = document.getElementById(id);
        const list = document.getElementById(id + '-list');
        if (!st || !inp || !list) return;
        const q = inp.value.trim();
        st.filtered = st.options.filter(o => this._match(o, q));

        if (!st.filtered.length) {
            list.innerHTML = `<div class="ss-empty">No approved entry matches "${
                q.replace(/</g, '&lt;')}". Add it to the database and have it approved first.</div>`;
            list.classList.add('open');
            return;
        }
        let html = '', lastGroup = null;
        st.filtered.forEach((o, i) => {
            if (o.group && o.group !== lastGroup) {
                html += `<div class="ss-group">${String(o.group).replace(/</g, '&lt;')}</div>`;
                lastGroup = o.group;
            }
            html += `<div class="ss-opt${i === st.cursor ? ' sel' : ''}" data-i="${i}"
                        onmousedown="event.preventDefault();SearchSelect.choose('${id}',${i})">
                        <span class="ss-opt-label">${this._hl(o.label, q)}</span>
                        ${o.meta ? `<span class="ss-opt-meta">${String(o.meta).replace(/</g, '&lt;')}</span>` : ''}
                     </div>`;
        });
        list.innerHTML = html;
        list.classList.add('open');
        const sel = list.querySelector('.ss-opt.sel');
        if (sel) sel.scrollIntoView({ block: 'nearest' });
    },

    onFocus(id) { const st = this._reg[id]; if (st) st.cursor = -1; this._paint(id); },
    onInput(id) { const st = this._reg[id]; if (st) st.cursor = -1; this._paint(id); },

    onBlur(id) {
        // let a click on an option land first
        setTimeout(() => {
            const list = document.getElementById(id + '-list');
            if (list) list.classList.remove('open');
            // restore the committed label if the user typed then left
            const st = this._reg[id];
            const inp = document.getElementById(id);
            const hid = document.getElementById(id + '-val');
            if (st && inp && hid) {
                const cur = st.options.find(o => String(o.value) === String(hid.value));
                if (cur) inp.value = cur.label;
                else if (!hid.value) inp.value = '';
            }
        }, 140);
    },

    onKey(id, e) {
        const st = this._reg[id];
        if (!st) return;
        if (e.key === 'ArrowDown') {
            st.cursor = Math.min(st.cursor + 1, st.filtered.length - 1); this._paint(id); e.preventDefault();
        } else if (e.key === 'ArrowUp') {
            st.cursor = Math.max(st.cursor - 1, 0); this._paint(id); e.preventDefault();
        } else if (e.key === 'Enter') {
            if (st.cursor >= 0) { this.choose(id, st.cursor); e.preventDefault(); }
        } else if (e.key === 'Escape') {
            const list = document.getElementById(id + '-list');
            if (list) list.classList.remove('open');
        }
    },

    choose(id, i) {
        const st = this._reg[id];
        if (!st) return;
        const opt = st.filtered[i];
        if (!opt) return;
        const inp = document.getElementById(id);
        const hid = document.getElementById(id + '-val');
        if (inp) inp.value = opt.label;
        if (hid) hid.value = opt.value;
        const list = document.getElementById(id + '-list');
        if (list) list.classList.remove('open');
        if (st.onSelect) {
            try { st.onSelect(opt.value, opt); }
            catch (err) { console.error('SearchSelect onSelect:', err); }
        }
    },

    /** value(id) - the committed value, for save-time reads. */
    value(id) {
        const hid = document.getElementById(id + '-val');
        return hid ? hid.value : '';
    }
};

;

/* ═══════ js/core/app.js ═══════ */
// ================================================================
//  core/app.js — Application shell: routing, session, role checks
//
//  PURPOSE: The App singleton owns the current user (persisted in
//  localStorage under 'fctc_user'), page navigation, role gating
//  (release-cash = superadmin only, record-cash = approvers only),
//  the light/dark theme toggle, and the pending-approvals badge.
//
//  NOTE: navigate() delegates to each page module's load(); page
//  modules are attached to window by their own files under js/pages/.
// ================================================================

const App = {
    currentUser: null,
    _pendingCount: 0,

    init() {
        // v7.0: a stored profile is not a session — without a valid token
        // the server will reject everything, so require the token too and
        // re-confirm identity with the server (this also restores the
        // View As state after a refresh).
        // v7.0.1: a profile saved by the OLD login system has no token.
        // Clear it silently so the user simply sees the login page instead
        // of a confusing "session expired" error on first load.
        if (localStorage.getItem('fctc_user') && !getSessionToken()) {
            try { localStorage.removeItem('fctc_user'); } catch (_) {}
            this.currentUser = null;
        }

        const saved = localStorage.getItem('fctc_user');
        if (saved && getSessionToken()) {
            try {
                this.currentUser = JSON.parse(saved);
                if (this.currentUser && this.currentUser.loggedIn) {
                    this.updateUserBadges();
                    this.navigate('home');
                    this.refreshIdentity();
                    return;
                }
            } catch (_) {}
        }
        setSessionToken('');
        this.navigate('login');
        const theme = localStorage.getItem('fctc_theme') || 'light';
        if (theme === 'dark') document.documentElement.setAttribute('data-theme', 'dark');
    },

    async navigate(page) {
        // ─── RELEASE CASH: Super Admin only ──────────────────
        if (page === 'release-cash' && !this.isSuperAdmin()) {
            UI.toast('Access denied. Super Admin only.', 'error');
            if (page !== 'home') {
                setTimeout(() => this.navigate('home'), 800);
                return;
            }
        }

        // ─── KNOWLEDGE BASE: the three databases moved here ───
        // v11 BATCH F1: Materials, Equipment and Manpower are no longer
        // pages of their own. The old names still resolve, so existing
        // links, the home tiles, the search page's deep links and
        // anything a browser has cached keep working — they just land on
        // the Knowledge Base with the right tab open.
        const KB_ALIASES = { materials: 'materials', equipment: 'equipment', manpower: 'manpower' };
        if (KB_ALIASES[page]) {
            const tab = KB_ALIASES[page];
            page = 'knowledge';
            this._kbTab = tab;
        } else if (page === 'knowledge' || page === 'knowledge-base') {
            page = 'knowledge';
            if (!this._kbTab) this._kbTab = 'materials';
        }

        // ─── PRINT TEMPLATE: Super Admin only ─────────────────
        // This is the company's identity on documents that go to
        // clients, so it is guarded here and again on the server in
        // savePrintTemplate().
        if (page === 'print-template' && !this.isSuperAdmin()) {
            UI.toast('Access denied. Super Admin only.', 'error');
            setTimeout(() => this.navigate('home'), 800);
            return;
        }

        // ─── RECORD CASH: Approvers only ──────────────────────
        if (page === 'record-cash' && !this.isApprover()) {
            UI.toast('Access denied. Approvers only.', 'error');
            if (page !== 'home') {
                setTimeout(() => this.navigate('home'), 800);
                return;
            }
        }

        // v7.0.1: these hit the API, so they must not run without a
        // session — otherwise a stale localStorage profile (or the login
        // page itself) triggers calls that fail with "Session expired".
        if (getSessionToken()) {
            if (page === 'portfolio') {
                PortfolioPage.load();
            }
            if (page === 'request') {
                loadProjectsDropdown();
            }
            if (page === 'record-cash') {
                setTimeout(loadIncomingProjectsDropdown, 100);
            }
        }

        // v12: one shell for the whole app. Rendered on every navigation
        // so the highlighted group can never drift from where you are.
        if (typeof Nav !== 'undefined') Nav.render(page);

        // v28: the chat dock is part of the shell, so it is started once
        // and simply keeps running — its open threads, scroll position
        // and poll all survive moving between pages. The login screen is
        // the one place it must not appear.
        if (typeof ChatDock !== 'undefined') {
            if (page === 'login' || !this.currentUser) ChatDock.stop();
            else ChatDock.start();
        }

        document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
        const target = document.getElementById('page-' + page);
        if (target) {
            target.classList.add('active');
            target.setAttribute('tabindex', '-1');
            target.focus({ preventScroll: false });
            window.scrollTo({ top: 0, behavior: 'instant' });
        }
        
        if (page === 'home') await HomePage.load();
        if (page === 'finance') await FinancePage.load();
        // v11 BATCH F1: one call replaces three. KnowledgeBasePage loads
        // each database lazily on first open, so switching to it to read
        // a lesson no longer pulls three full catalogues over the wire.
        if (page === 'knowledge') await KnowledgeBasePage.load(this._kbTab || 'materials');
        if (page === 'quotations') await QuotationsPage.load();   // v11 BATCH F2
        if (page === 'purchase-requests') await PurchaseRequestsPage.load();   // v11 BATCH G1
        if (page === 'payables') await PayablesPage.load();   // v11 BATCH G2
        if (page === 'approvals') await ApprovalsPage.load();
        if (page === 'print-template') await PrintTemplatePage.load();
        if (page === 'release-cash') {
            setTimeout(loadReleaseDropdown, 100);
        }
        if (page === 'liquidate') {
            setTimeout(loadLiquidateDropdown, 100);   // v4: auto-list reviewed advances to liquidate
            setTimeout(loadLiquidationVendors, 120);  // v11 BATCH H3: supplier names + TIN
        }

        this.updateUserBadges();
        await this.updateApprovalBadge();

        document.querySelectorAll('.topbar .actions').forEach(el => el.classList.remove('open'));
    },


    // ══════════ v7.0: VIEW AS (impersonation) ══════════

    /**
     * Super Admin only. The target is stored on the SERVER session, never
     * in the browser — otherwise "who am I" would again be a value the
     * client controls, which is the exact hole this release closes.
     * Every action performed while viewing-as is logged as
     * "real@email (as target@email)", so the audit trail never loses the
     * real actor.
     */
    async openViewAs() {
        let users = [];
        try { users = await DataService.getViewAsUsers(); }
        catch (err) { UI.toast('' + err.message, 'error'); return; }

        const overlay = document.createElement('div');
        overlay.id = 'viewAsModal';
        overlay.style.cssText = 'position:fixed;inset:0;background:rgba(28,35,33,.55);z-index:1200;display:flex;align-items:center;justify-content:center;padding:20px;';
        overlay.innerHTML = `
            <div style="background:var(--surface);border:1px solid var(--line);border-radius:12px;max-width:420px;width:100%;max-height:80vh;display:flex;flex-direction:column;overflow:hidden;">
                <div style="padding:13px 18px;border-bottom:1px solid var(--line);background:var(--blueprint-tint);display:flex;justify-content:space-between;align-items:center;">
                    <h3 style="font-family:'Oswald';font-size:13px;text-transform:uppercase;color:var(--blueprint);margin:0;">View As — Test Another User</h3>
                    <span style="cursor:pointer;color:var(--ink-soft);" onclick="document.getElementById('viewAsModal').remove()">${Icon.close({size:12})}</span>
                </div>
                <div style="padding:14px 18px;overflow:auto;">
                    <div style="font-size:11.5px;color:var(--ink-soft);margin-bottom:10px;line-height:1.5;">
                        You will see the system exactly as they do. Every action is still recorded under your real identity.
                    </div>
                    ${users.map(u => `
                        <button onclick="App.applyViewAs('${u.email}')" style="width:100%;text-align:left;display:flex;align-items:center;gap:10px;padding:10px;border:1px solid var(--line);border-radius:8px;margin-bottom:8px;background:var(--surface);cursor:pointer;">
                            <span style="width:26px;height:26px;border-radius:50%;background:var(--blueprint);color:#fff;display:inline-flex;align-items:center;justify-content:center;font-family:'Oswald';font-size:10px;">${(u.name || u.email).slice(0, 2).toUpperCase()}</span>
                            <span style="font-weight:600;font-size:12.5px;">${u.name || u.email}</span>
                            <span style="font-family:'IBM Plex Mono';font-size:10px;color:var(--ink-soft);margin-left:auto;border:1px solid var(--line);border-radius:4px;padding:1px 6px;">${u.role}</span>
                        </button>`).join('')}
                </div>
            </div>`;
        overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
        document.body.appendChild(overlay);
    },

    async applyViewAs(email) {
        try {
            await DataService.setViewAs(email);
            const m = document.getElementById('viewAsModal');
            if (m) m.remove();
            await this.refreshIdentity();
            UI.toast('Viewing as ' + email, 'success');
            this.navigate('home');
        } catch (err) { UI.toast('' + err.message, 'error'); }
    },

    async stopViewAs() {
        try {
            await DataService.setViewAs('');
            await this.refreshIdentity();
            UI.toast('Back to your own account.', 'success');
            this.navigate('home');
        } catch (err) { UI.toast('' + err.message, 'error'); }
    },

    /** refreshIdentity - re-reads who the server thinks we are. */
    async refreshIdentity() {
        try {
            const me = await DataService.whoAmI();
            this.currentUser = me.user;
            localStorage.setItem('fctc_user', JSON.stringify(me.user));
            this._realUser = me.realUser;
            this._impersonating = me.impersonating;
            this.renderImpersonationBanner();
            this.updateUserBadges();
        } catch (err) { /* session handling covers this */ }
    },

    renderImpersonationBanner() {
        let bar = document.getElementById('impersonationBar');
        if (!this._impersonating) { if (bar) bar.remove(); return; }
        if (!bar) {
            bar = document.createElement('div');
            bar.id = 'impersonationBar';
            bar.style.cssText = 'position:sticky;top:0;z-index:900;background:var(--amber);color:#1C2321;padding:7px 14px;font-size:12px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;';
            document.body.prepend(bar);
        }
        bar.innerHTML = `${Icon.eye({size:13})} <b>Viewing as ${(this.currentUser || {}).email || ''}</b>
            <span style="opacity:.8;">— this is not your own account (${(this._realUser || {}).email || ''}). All actions remain logged under your real identity.</span>
            <button onclick="App.stopViewAs()" style="margin-left:auto;background:#1C2321;color:#fff;border:none;border-radius:6px;padding:4px 12px;font-size:11px;cursor:pointer;">Stop</button>`;
    },

    logout() {
        // v7.0: revoke the session server-side, not just locally — a
        // token left valid on the server would still work if copied.
        try { DataService.logout(); } catch (e) {}
        // Stop the heartbeat before the token goes, or the poll keeps
        // firing against a revoked session and reports you as online.
        if (typeof ChatDock !== 'undefined') ChatDock.stop();
        setSessionToken('');
        localStorage.removeItem('fctc_user');
        this.currentUser = null;
        this.navigate('login');
        UI.toast('Logged out.', 'success');
    },

    toggleTheme() {
        const html = document.documentElement;
        const current = html.getAttribute('data-theme');
        const next = current === 'dark' ? 'light' : 'dark';
        html.setAttribute('data-theme', next);
        localStorage.setItem('fctc_theme', next);
        UI.toast(next === 'dark' ? 'Dark mode' : 'Light mode', 'success');
    },

    getUser() {
        return this.currentUser;
    },

    hasRole(role) {
        if (!this.currentUser) return false;
        return this.currentUser.role === role;
    },

    isAdmin() {
        return this.hasRole('admin') || this.hasRole('superadmin');
    },

    isApprover() {
        return this.hasRole('approver') || this.hasRole('admin') || this.hasRole('superadmin');
    },

    // ✅ NEW: Check if user is Super Admin
    isSuperAdmin() {
        return this.hasRole('superadmin');
    },

    isRequestOnly() {
        return this.hasRole('request-only');
    },

    canApprove() {
        return this.isApprover() || this.isAdmin();
    },

    canSubmit() {
        return true;
    },

    updateUserBadges() {
        const user = this.getUser();
        if (!user) return;

        // v7.0: superadmin-only controls (e.g. View As). Note this is a
        // convenience, not a control — the server enforces the real check.
        const isSA = user.role === 'superadmin';
        document.querySelectorAll('.superadmin-only').forEach(el => {
            el.style.display = isSA ? '' : 'none';
        });
        
        const name = user.name || 'User';
        const email = user.email || '';
        
        document.querySelectorAll('.requester-badge').forEach(el => {
            const strong = el.querySelector('strong');
            if (strong) {
                strong.textContent = name;
            } else {
                const text = el.textContent;
                const colonIndex = text.indexOf(':');
                if (colonIndex > -1) {
                    const prefix = text.substring(0, colonIndex + 1);
                    el.textContent = `${prefix} ${name}`;
                } else {
                    el.textContent = `Requesting as: ${name}`;
                }
            }
        });
        
        const homeLabel = document.getElementById('home-user-label');
        if (homeLabel) {
            const roleLabel = user.roleLabel || user.role || 'User';
            homeLabel.textContent = `${roleLabel} — ${name}`;
        }
    },

    async updateApprovalBadge() {
        if (!getSessionToken()) return;   // v7.0.1: no session, no call
        try {
            const user = this.getUser();
            if (!user) return;
            
            const pendingData = await DataService.getPendingApprovals();
            const userEmail = this.getUser().email.toLowerCase();

            // Count pending cash advances (excluding self)
            const pendingCashAdvances = (pendingData.cashAdvances || []).filter(function(r) {
                return r.requestorEmail && r.requestorEmail.toLowerCase() !== userEmail;
            });
            
            // Count reviewing releases (for Admins)
            const pendingReleases = (pendingData.releases || []).filter(function(r) {
                return r.releasedBy && r.releasedBy.toLowerCase() !== userEmail;
            });
            
            const pendingMaterials = (pendingData.materials || []).filter(function(m) {
                return m.requestedBy && m.requestedBy.toLowerCase() !== userEmail;
            });
            
            const pendingEquipment = (pendingData.equipment || []).filter(function(e) {
                return e.requestedBy && e.requestedBy.toLowerCase() !== userEmail;
            });
            
            const pendingEstimates = pendingData.estimates || [];
            const pendingDailyRecords = (pendingData.dailyRecords || []).filter(function(d) {
                return d.createdBy && d.createdBy.toLowerCase() !== userEmail;
            });

            // v3: incoming cash + manpower now count toward the badge
            const pendingIncoming = (pendingData.incomingCash || []).filter(function(r) {
                return r.requestorEmail && r.requestorEmail.toLowerCase() !== userEmail;
            });
            const pendingManpower = (pendingData.manpower || []).filter(function(m) {
                return m.requestedBy && m.requestedBy.toLowerCase() !== userEmail;
            });

            this._pendingCount = pendingCashAdvances.length + pendingReleases.length + 
                                 pendingIncoming.length + pendingManpower.length +
                                 pendingMaterials.length + pendingEquipment.length + 
                                 pendingEstimates.length + pendingDailyRecords.length;
            
            document.querySelectorAll('.t-badge, #approvalBadgeHome').forEach(el => {
                el.textContent = this._pendingCount;
            });
        } catch (err) {
            console.error('Error updating badge:', err);
        }
    }
};

// ─── TOGGLE MENU (mobile topbar) ──────────────────────────────
function toggleMenu() {
    document.querySelectorAll('.topbar .actions').forEach(el => el.classList.toggle('open'));
}
;

/* ═══════ js/core/auth.js ═══════ */
// ================================================================
//  core/auth.js — Login form handler
//
//  PURPOSE: Validates the login form, authenticates through
//  DataService.login() (backend Users sheet is the single source of
//  truth for accounts), persists the session and enters the app.
//
//  CLEANUP NOTE: the legacy client-side USER_DB / ROLE_LABELS tables
//  that previously lived in this file were removed — they were dead
//  code with zero references; authentication has been fully
//  server-side since the DataService bridge was introduced.
// ================================================================

// ─── LOGIN HANDLER ────────────────────────────────────────────

async function handleLogin(e) {
    e.preventDefault();
    const email = document.getElementById('login-email').value.trim().toLowerCase();
    const pass = document.getElementById('login-pass').value.trim();
    let valid = true;

    if (!email) {
        document.getElementById('login-email-field').classList.add('error');
        valid = false;
    } else {
        document.getElementById('login-email-field').classList.remove('error');
    }
    if (!pass) {
        document.getElementById('login-pass-field').classList.add('error');
        valid = false;
    } else {
        document.getElementById('login-pass-field').classList.remove('error');
    }
    if (!valid) return false;

    // ── v18: THE LOGIN BUTTON SAYS IT IS WORKING ──
    // Sign-in is the slowest call in the system — a cold Apps Script
    // plus a password hash — and it was the one button with no feedback
    // at all. People pressed it repeatedly, and every extra press counts
    // against the five-attempt lockout even though the first one was
    // fine. Somebody with the right password could lock themselves out
    // by being impatient.
    const btn = document.getElementById('loginBtn') ||
                document.querySelector('#loginForm button[type="submit"]');
    const restore = () => {
        if (!btn) return;
        btn.disabled = false;
        btn.classList.remove('is-busy');
        btn.innerHTML = btn.dataset.label || 'Sign in';
    };
    if (btn) {
        btn.dataset.label = btn.innerHTML;
        btn.disabled = true;
        btn.classList.add('is-busy');
        btn.innerHTML = '<span class="busy-dot"></span>Signing in...';
    }

    let user;
    try {
        // v7.0: the server issues a session token; the browser stores the
        // token, not an identity it could edit.
        const res = await DataService.loginWithPassword(email, pass);
        setSessionToken(res.token);
        user = res.user;
    } catch (err) {
        restore();
        UI.toast('' + err.message, 'error');
        document.getElementById('login-pass-field').classList.add('error');
        return false;
    }

    // The button stays busy through the redirect — the work is not done
    // when the token arrives, it is done when the dashboard is on
    // screen, and re-enabling it here would invite a second submit
    // during the load.
    if (btn) btn.innerHTML = '<span class="busy-dot"></span>Loading your data...';

    localStorage.setItem('fctc_user', JSON.stringify(user));
    App.currentUser = user;

    App.updateUserBadges();

    const label = document.getElementById('home-user-label');
    if (label) {
        label.textContent = `${user.roleLabel} — ${user.name}`;
    }

    UI.toast(`Welcome, ${user.name}! (${user.roleLabel})`, 'success');
    App.navigate('home');
    return false;
}
;

/* ═══════ js/core/ui.js ═══════ */
// ================================================================
//  core/ui.js — Shared UI primitives: toast, loading, confirm, lightbox
//
//  PURPOSE: Small presentation helpers used by every page module.
//    UI.toast(msg, type)      -> transient notification
//    UI.showLoading(el)       -> loader overlay while fetching
//    Confirm.open(title, msg) -> Promise<boolean> dialog
//    Lightbox                 -> fullscreen photo viewer with keys
// ================================================================

// ─── UI HELPERS ──────────────────────────────────────────────────

const UI = {
    toast(msg, type = 'info') {
        const el = document.getElementById('toast');
        const icon = type === 'error' ? Icon.xCircle({ size: 18 }) :
                     type === 'success' ? Icon.checkCircle({ size: 18 }) :
                     Icon.warning({ size: 18 });
        el.innerHTML = `<span class="toast-icon">${icon}</span><span class="toast-msg">${msg}</span>`;
        el.className = 'toast';
        if (type === 'error') el.classList.add('error');
        if (type === 'success') el.classList.add('success');
        el.classList.add('show');
        clearTimeout(el._timer);
        el._timer = setTimeout(() => el.classList.remove('show'), 2800);
    },
    
    showLoading(container) {
        if (!container) return;
        container.innerHTML =
            `<div class="loading-overlay"><div class="loader"></div><p>Loading data...</p></div>`;
    },

    /**
     * showSkeleton (v6.5) - Structure-aware placeholder. Instead of a
     * blank spinner, the page's shape (header, KPI cards, rows) appears
     * immediately and shimmers until the real data lands, so the wait
     * feels far shorter and the layout doesn't jump on arrival.
     */
    showSkeleton(container, kind) {
        if (!container) return;
        const bar = (w, h, mt) =>
            `<div class="sk-bar" style="width:${w};height:${h || '12px'};margin-top:${mt || '8px'};"></div>`;
        const card = () =>
            `<div class="sk-card">${bar('55%', '9px', '0')}${bar('80%', '20px')}${bar('40%', '9px')}</div>`;
        let body = '';
        if (kind === 'project') {
            body = `
                <div class="sk-head">${bar('38%', '22px', '0')}${bar('22%', '11px')}</div>
                <div class="sk-tabs">${[1,2,3,4,5,6].map(() => '<div class="sk-tab"></div>').join('')}</div>
                <div class="sk-kpis">${[1,2,3,4].map(card).join('')}</div>
                <div class="sk-panel">${[1,2,3,4,5].map(() => bar('100%', '14px', '12px')).join('')}</div>`;
        } else {
            body = `
                <div class="sk-head">${bar('30%', '20px', '0')}</div>
                <div class="sk-kpis">${[1,2,3,4].map(card).join('')}</div>
                <div class="sk-panel">${[1,2,3,4].map(() => bar('100%', '14px', '12px')).join('')}</div>`;
        }
        container.innerHTML = `<div class="skeleton" aria-busy="true" aria-label="Loading">${body}</div>`;
    },
    
    setContent(container, html) {
        if (container) container.innerHTML = html;
    }
};

// ─── CONFIRM DIALOG ─────────────────────────────────────────────

const Confirm = {
    _resolve: null,
    open(title, message) {
        return new Promise((resolve) => {
            document.getElementById('confirmTitle').textContent = title;
            document.getElementById('confirmMessage').textContent = message;
            document.getElementById('confirmOverlay').classList.add('open');
            this._resolve = resolve;
        });
    },
    confirm() {
        document.getElementById('confirmOverlay').classList.remove('open');
        if (this._resolve) this._resolve(true);
        this._resolve = null;
    },
    cancel() {
        document.getElementById('confirmOverlay').classList.remove('open');
        if (this._resolve) this._resolve(false);
        this._resolve = null;
    }
};

// ─── LIGHTBOX ──────────────────────────────────────────────────

const Lightbox = {
    _images: [],
    _current: 0,
    open(images, index) {
        this._images = images;
        this._current = index;
        this._show();
        document.getElementById('lightbox').classList.add('open');
        document.body.style.overflow = 'hidden';
        document.addEventListener('keydown', this._onKey);
    },
    close() {
        document.getElementById('lightbox').classList.remove('open');
        document.body.style.overflow = '';
        document.removeEventListener('keydown', this._onKey);
    },
    prev() {
        if (this._images.length > 0) {
            this._current = (this._current - 1 + this._images.length) % this._images.length;
            this._show();
        }
    },
    next() {
        if (this._images.length > 0) {
            this._current = (this._current + 1) % this._images.length;
            this._show();
        }
    },
    _show() {
        const img = document.getElementById('lbImg');
        const counter = document.getElementById('lbCounter');
        if (this._images.length > 0) {
            img.src = this._images[this._current];
            counter.textContent = `${this._current + 1} / ${this._images.length}`;
        }
    },
    _onKey(e) {
        if (e.key === 'Escape') Lightbox.close();
        if (e.key === 'ArrowLeft') Lightbox.prev();
        if (e.key === 'ArrowRight') Lightbox.next();
    }
};

/**
 * fmtMoney / fmtNum (v5) - System-wide number formatting.
 * fmtMoney(12345.6) -> "12,345.60"   (always 2 decimals, comma-grouped)
 * fmtNum(12345.6)   -> "12,345.6"    (comma-grouped, no forced decimals)
 * Every peso figure in the UI should render as ₱${fmtMoney(x)}.
 */
/**
 * fmtAxisMoney (v6.6) - THE money formatter for chart axes, system-wide.
 * Under a million: ₱850k. From a million up: ₱1M, ₱1.15M, ₱20.6M —
 * never "1,000k". Every chart's money axis must use this.
 */
function fmtAxisMoney(v) {
    const a = Math.abs(v);
    if (a >= 1000000) {
        const m = v / 1000000;
        return '₱' + (Number.isInteger(m) ? m : +m.toFixed(2)) + 'M';
    }
    if (a >= 1000) return '₱' + Math.round(v / 1000) + 'k';
    return '₱' + v;
}

function fmtMoney(n) {
    const v = Number(n) || 0;
    return v.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function fmtNum(n) {
    const v = Number(n) || 0;
    return v.toLocaleString('en-PH', { maximumFractionDigits: 2 });
}
;

/* ═══════ js/core/modals.js ═══════ */
// ================================================================
//  core/modals.js — Print/detail modals
//
//  PURPOSE: Read-only, print-friendly views:
//    PrintModal        -> Daily Site Record
//    MatPrintModal     -> Material datasheet
//    EquipPrintModal   -> Equipment datasheet
//    SOWBreakdownModal -> SOW estimate breakdown (BOM/labor/equipment/indirect)
//  Each modal renders into a fixed container in index.html and locks
//  body scroll while open.
// ================================================================

// ─── PRINT MODAL ─────────────────────────────────────────────────

/**
 * driveImgSrc (v5 PHOTO FIX) - Old records stored Drive VIEWER page URLs
 * (…/file/d/ID/view…), which always render broken inside <img>. This
 * rewrites any Drive link to the /thumbnail endpoint, which streams the
 * actual image. New uploads already store the thumbnail form.
 */
function driveImgSrc(url) {
    if (!url) return url;
    const m = String(url).match(/drive\.google\.com\/file\/d\/([\w-]+)/) ||
              String(url).match(/[?&]id=([\w-]+)/);
    if (m && String(url).indexOf('thumbnail') === -1) {
        return 'https://drive.google.com/thumbnail?id=' + m[1] + '&sz=w1200';
    }
    return url;
}

const PrintModal = {
    /**
     * open(record, meta) — meta (v3, optional):
     *   { projectName, preparedBy } shown in the header so the modal
     *   matches the daily record FORM header.
     */
    open(record, meta) {
        const modal = document.getElementById('printModal');
        const body = document.getElementById('printBody');
        body.innerHTML = this.renderPrintView(record, meta || {});
        modal.classList.add('open');
        document.body.style.overflow = 'hidden';
    },
    close() {
        document.getElementById('printModal').classList.remove('open');
        document.body.style.overflow = '';
    },
    /** _sowLabel (v9 — item 3) - "1.a — Excavation" style label from
     *  meta.sowNames (id → description map supplied by ProjectPage). */
    _sowLabel(scope, meta) {
        if (!scope) return '—';
        const name = meta && meta.sowNames ? meta.sowNames[scope] : '';
        return name ? scope + ' — ' + name : scope;
    },

    renderPrintView(r, meta) {
        meta = meta || {};
        const totalManpower = r.manpower ? r.manpower.reduce((s, m) => s + (parseInt(m.count) || 0), 0) : 0;
        const statusCls = r.status === 'On Track' ? 'ontrack' : r.status === 'Delayed' ? 'delayed' : 'completed';
        let html = `
                <div class="print-header">
                    <h2>Daily Site Record</h2>
                    <div class="print-meta">${r.date} · <span class="stamp ${statusCls}" style="transform:none;font-size:10px;">${r.status}</span></div>
                </div>
                <div class="print-section"><div class="ps-title">Report Header</div><div class="ps-grid">
                    <div class="item"><span class="label">Project</span><span class="value">${meta.projectName || '—'}</span></div>
                    <div class="item"><span class="label">Prepared By</span><span class="value">${meta.preparedBy || r.createdBy || '—'}</span></div>
                    <div class="item"><span class="label">Report Date</span><span class="value">${r.date || '—'}</span></div>
                </div></div>
                <div class="print-section"><div class="ps-title">Weather & Status</div><div class="ps-grid">
                    <div class="item"><span class="label">Weather AM</span><span class="value">${r.weatherAM || '—'}</span></div>
                    <div class="item"><span class="label">Weather PM</span><span class="value">${r.weatherPM || '—'}</span></div>
                    <div class="item"><span class="label">Status</span><span class="value">${r.status}</span></div>
                </div></div>
                <div class="print-section"><div class="ps-title">Manpower <span style="font-weight:400;font-size:10px;color:var(--ink-soft);">(Total: ${totalManpower})</span></div>
                    ${r.manpower && r.manpower.length ? (r.manpower.some(m => m.name || m.amIn || m.pmIn || m.otIn) ? `<table class="ps-table"><thead><tr><th>Name</th><th>Trade / Role</th><th>#</th><th>AM In</th><th>AM Out</th><th>PM In</th><th>PM Out</th><th>OT In</th><th>OT Out</th><th>Signature</th></tr></thead><tbody>${r.manpower.map(m => `<tr><td>${m.name || '—'}</td><td>${m.role || '—'}</td><td>${m.count || 1}</td><td>${m.amIn || '—'}</td><td>${m.amOut || '—'}</td><td>${m.pmIn || '—'}</td><td>${m.pmOut || '—'}</td><td>${m.otIn || '—'}</td><td>${m.otOut || '—'}</td><td style="text-align:center;">${m.signature ? `<img class="mp-sig" src="${driveImgSrc(m.signature)}" alt="" onerror="this.style.display='none'" />` : ''}</td></tr>`).join('')}</tbody></table>` : `<table class="ps-table"><thead><tr><th>Trade / Role</th><th>Number Present</th><th>Signature</th></tr></thead><tbody>${r.manpower.map(m => `<tr><td>${m.role}</td><td>${m.count}</td><td style="text-align:center;">${m.signature ? `<img class="mp-sig" src="${driveImgSrc(m.signature)}" alt="" onerror="this.style.display='none'" />` : ''}</td></tr>`).join('')}</tbody></table>`) : `<p style="font-size:12px;color:var(--ink-soft);">No manpower recorded.</p>`}
                </div>
                <div class="print-section"><div class="ps-title">Equipment on Site</div>
                    ${r.equipment && r.equipment.length ? `<table class="ps-table"><thead><tr><th>Equipment</th><th>Qty</th><th>Status</th><th>Remarks</th></tr></thead><tbody>${r.equipment.map(e => `<tr><td>${e.name}</td><td>${e.qty}</td><td>${e.status || '—'}</td><td>${e.remarks || '—'}</td></tr>`).join('')}</tbody></table>` : `<p style="font-size:12px;color:var(--ink-soft);">No equipment recorded.</p>`}
                </div>
                <div class="print-section"><div class="ps-title">Work Accomplished</div>
                    ${r.workAccomplished && r.workAccomplished.length ? `<table class="ps-table"><thead><tr><th>Location/Area</th><th>Scope of Work</th><th>Description</th><th>% Complete</th></tr></thead><tbody>${r.workAccomplished.map(w => `<tr><td>${w.location || '—'}</td><td>${PrintModal._sowLabel(w.scope, meta)}</td><td>${w.description || '—'}</td><td>${w.percentComplete || 0}%</td></tr>`).join('')}</tbody></table>` : `<p style="font-size:12px;color:var(--ink-soft);">No work accomplished recorded.</p>`}
                    ${PrintModal._photoGrid((r.workAccomplished || []).filter(w => w.image).map(w => ({
                        url: w.image,
                        caption: 'Work: ' + [PrintModal._sowLabel(w.scope, meta), w.description || w.location].filter(Boolean).join(' — ')
                    })))}
                </div>
                <div class="print-section"><div class="ps-title">Materials Delivered</div>
                    ${r.materialsDelivered && r.materialsDelivered.length ? `<table class="ps-table"><thead><tr><th>Material</th><th>Qty</th><th>Unit</th><th>Supplier / DR No.</th></tr></thead><tbody>${r.materialsDelivered.map(m => `<tr><td>${m.material}</td><td>${m.qty}</td><td>${m.unit || '—'}</td><td>${m.supplier || '—'}</td></tr>`).join('')}</tbody></table>` : `<p style="font-size:12px;color:var(--ink-soft);">No materials delivered recorded.</p>`}
                </div>
                <div class="print-section"><div class="ps-title">Materials Used</div>
                    ${r.materialsUsed && r.materialsUsed.length ? `<table class="ps-table"><thead><tr><th>Material</th><th>Qty Used</th><th>Unit</th><th>Used For (SOW)</th></tr></thead><tbody>${r.materialsUsed.map(m => `<tr><td>${m.material}</td><td>${m.qty}</td><td>${m.unit || '—'}</td><td>${m.sow || '—'}</td></tr>`).join('')}</tbody></table>` : `<p style="font-size:12px;color:var(--ink-soft);">No materials used recorded.</p>`}
                </div>
                <div class="print-section"><div class="ps-title">Issues / Delays</div>
                    ${r.issues && r.issues.length ? `<table class="ps-table"><thead><tr><th>Description</th><th>Cause</th><th>Time Lost (hrs)</th></tr></thead><tbody>${r.issues.map(iss => `<tr><td>${iss.description || '—'}</td><td>${iss.cause || '—'}</td><td>${iss.timeLost || 0}</td></tr>`).join('')}</tbody></table>` : `<p style="font-size:12px;color:var(--ink-soft);">No issues recorded.</p>`}
                    ${PrintModal._photoGrid((r.issues || []).filter(i => i.image).map(i => ({
                        url: i.image,
                        caption: 'Issue: ' + (i.description || i.cause || '')
                    })))}
                </div>
                <div class="print-section"><div class="ps-title">Visitors</div>
                    ${r.visitors && r.visitors.length ? `<table class="ps-table"><thead><tr><th>Name</th><th>Company / Role</th><th>Purpose</th><th>Time In</th><th>Time Out</th><th>Remarks</th></tr></thead><tbody>${r.visitors.map(v => `<tr><td>${v.name}</td><td>${v.company || '—'} ${v.role ? '· ' + v.role : ''}</td><td>${v.purpose || '—'}</td><td>${v.timeIn || '—'}</td><td>${v.timeOut || '—'}</td><td>${v.remarks || '—'}</td></tr>`).join('')}</tbody></table>` : `<p style="font-size:12px;color:var(--ink-soft);">No visitors recorded.</p>`}
                </div>
                ${(r.photos && r.photos.length) ? `
                <div class="print-section"><div class="ps-title">Site Photos <span style="font-weight:400;font-size:10px;color:var(--ink-soft);">(${r.photos.length})</span></div>
                    ${PrintModal._photoGrid(r.photos.map((p, i) => {
                        const isObj = p && typeof p === 'object';
                        return { url: isObj ? p.url : p, caption: (isObj && p.caption) ? p.caption : ('Site Photo ' + (i + 1)) };
                    }))}
                </div>` : ''}
                <div class="print-actions">
                    <button class="btn-primary" onclick="PrintDoc.print()">${Icon.printer({size:14})} Print</button>
                    <button class="btn-ghost" onclick="PrintModal.close()">Close</button>
                </div>`;
        return html;
    },

    /**
     * _photoGrid (v8) - Presentation-ready photo grid: the ACTUAL
     * pictures render (not just links), each with its caption so the
     * printout reads like a proper site report. Broken images collapse
     * to a note instead of a broken-icon box.
     */
    _photoGrid(items) {
        if (!items || !items.length) return '';
        return `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:12px;margin-top:10px;">
            ${items.map(it => `
                <figure style="margin:0;border:1px solid var(--line);border-radius:8px;overflow:hidden;background:var(--bg);break-inside:avoid;">
                    <img src="${driveImgSrc(it.url)}" alt="${(it.caption || '').replace(/"/g, '&quot;')}" loading="lazy"
                        style="width:100%;height:160px;object-fit:cover;display:block;"
                        onerror="this.style.display='none';this.nextElementSibling.style.display='block';" />
                    <div style="display:none;padding:18px 10px;text-align:center;font-size:11px;color:var(--ink-soft);">Image unavailable</div>
                    <figcaption style="padding:6px 9px;font-size:10.5px;line-height:1.4;color:var(--ink);border-top:1px solid var(--line);">${it.caption || '—'}</figcaption>
                </figure>`).join('')}
        </div>`;
    }
};

// ─── MATERIAL PRINT MODAL ──────────────────────────────────────

const MatPrintModal = {
    open(material) {
        const modal = document.getElementById('matPrintModal');
        const body = document.getElementById('matPrintBody');
        body.innerHTML = this.renderPrintView(material);
        modal.classList.add('open');
        document.body.style.overflow = 'hidden';
    },
    close() {
        document.getElementById('matPrintModal').classList.remove('open');
        document.body.style.overflow = '';
    },
    _e(v) {
        return String(v == null ? '' : v)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    },

    /**
     * renderPrintView (v11 BATCH H3) - The material datasheet.
     *
     * ── WHAT WAS WRONG ──
     * The heading read "Brand — Specifications". A brand is not an
     * identifier and a specification string is not a name, so two
     * different cements from the same supplier produced the same
     * heading, and a material with no brand produced "Material — ".
     *
     * Worse: the two fields the request form marks REQUIRED — Material
     * Name and Material Description — appeared NOWHERE in the datasheet.
     * The record you were shown was missing the only two things you had
     * to type to create it.
     *
     * The heading is now the ID and the description, and every field on
     * the request form has a place here, in the order the form asks for
     * them. Blank fields print as an em-dash rather than being dropped:
     * on a SPEC SHEET "not specified" is information, unlike a request
     * modal where an empty row is only noise.
     */
    renderPrintView(m) {
        const e = this._e.bind(this);
        const imgHtml = m.image
            ? `<img src="${driveImgSrc(m.image)}" alt="${e(m.name || m.id)}"
                    onerror="this.style.display='none'" />`
            : `<div class="no-img-placeholder">${Icon.package({size:28})}<br>No Image</div>`;
        const V = (label, val, full) =>
            `<div class="dg-item${full ? ' full' : ''}"><span class="dg-label">${label}</span><span class="dg-value">${e(val) || '—'}</span></div>`;

        return `
                <div class="detail-print-header">
                    <div class="dph-left">
                        <h2>${e(m.id)} — ${e(m.desc || m.description || m.name) || 'Material'}</h2>
                        <div class="dph-id">${e(m.name) || ''}${m.category ? ' · ' + e(m.category) : ''}${m.subcategory ? ' → ' + e(m.subcategory) : ''}</div>
                    </div>
                    <div class="dph-right">${imgHtml}</div>
                </div>

                <div class="print-section"><div class="ps-title">General Information</div>
                    <div class="detail-grid">
                        ${V('Material ID', m.id)}
                        ${V('Material Name', m.name)}
                        ${V('Description', m.desc || m.description, true)}
                        ${V('Category', m.category)}
                        ${V('Subcategory', m.subcategory)}
                        ${V('Unit of Measurement', m.unit)}
                    </div>
                </div>

                <div class="print-section"><div class="ps-title">Identification and Sourcing</div>
                    <div class="detail-grid">
                        ${V('Brand', m.brand)}
                        ${V('Model / Serial No.', m.model)}
                        ${V('Supplier', m.supplier)}
                        ${V('Reference Rate', m.rate ? '₱' + fmtMoney(parseFloat(m.rate) || 0) + (m.unit ? ' / ' + e(m.unit) : '') : '')}
                    </div>
                </div>

                <div class="print-section"><div class="ps-title">Technical Specifications</div>
                    <div class="detail-grid">
                        ${V('Specifications', m.specs, true)}
                        ${V('Grade', m.grade)}
                        ${V('Size / Dimension', m.size)}
                        ${V('Length', m.length)}
                        ${V('Thickness', m.thickness)}
                        ${V('Weight', m.weight)}
                        ${V('Standard / Code Reference', m.standardCode, true)}
                    </div>
                </div>

                <div class="print-section"><div class="ps-title">Additional Information</div>
                    <div class="detail-grid">
                        ${V('Typical Use / Application', m.application, true)}
                        ${V('Notes / Remarks', m.notes, true)}
                        ${V('Status', m.status)}
                        ${V('Requested By', m.requestedBy)}
                    </div>
                </div>

                ${AttachmentGallery.render(m.docsJSON || m.pdfUrl, 'Specification documents')}

                <div class="print-actions">
                    <button class="btn-primary" onclick="PrintDoc.print()">${Icon.printer({size:14})} Print</button>
                    <button class="btn-ghost" onclick="MatPrintModal.close()">Close</button>
                </div>`;
    }
};

// ─── EQUIPMENT PRINT MODAL ─────────────────────────────────────

/* v10: material datasheets can carry a PDF spec sheet plus the photo —
   both now render through the shared gallery. */
const EquipPrintModal = {
    open(equip) {
        const modal = document.getElementById('equipPrintModal');
        const body = document.getElementById('equipPrintBody');
        body.innerHTML = this.renderPrintView(equip);
        modal.classList.add('open');
        document.body.style.overflow = 'hidden';
    },
    close() {
        document.getElementById('equipPrintModal').classList.remove('open');
        document.body.style.overflow = '';
    },
    _e(v) {
        return String(v == null ? '' : v)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    },

    /**
     * renderPrintView (v11 BATCH H3) - The equipment datasheet.
     *
     * Same fault as the material one: the heading was "Brand — Model",
     * which is not an identifier — two identical excavators produced
     * identical headings and there was no way to tell which record you
     * had open. It leads with the equipment ID now.
     *
     * Every field the request form collects is present, in the order it
     * is asked for. Blanks print as an em-dash: on a spec sheet, "not
     * specified" is information.
     */
    renderPrintView(q) {
        const e = this._e.bind(this);
        const imgHtml = q.image
            ? `<img src="${driveImgSrc(q.image)}" alt="${e(q.name || q.id)}"
                    onerror="this.style.display='none'" />`
            : `<div class="no-img-placeholder">${Icon.wrench({size:28})}<br>No Image</div>`;
        const V = (label, val, full) =>
            `<div class="dg-item${full ? ' full' : ''}"><span class="dg-label">${label}</span><span class="dg-value">${e(val) || '—'}</span></div>`;
        const headline = q.desc || q.name ||
            [q.brand, q.model].filter(Boolean).join(' ') || q.category || 'Equipment';

        return `
                <div class="detail-print-header">
                    <div class="dph-left">
                        <h2>${e(q.id)} — ${e(headline)}</h2>
                        <div class="dph-id">${e(q.category) || ''}${q.ownership ? ' · ' + e(q.ownership) : ''}</div>
                    </div>
                    <div class="dph-right">${imgHtml}</div>
                </div>

                <div class="print-section"><div class="ps-title">General Information</div>
                    <div class="detail-grid">
                        ${V('Equipment ID', q.id)}
                        ${V('Name', q.name)}
                        ${V('Description', q.desc || q.description, true)}
                        ${V('Category / Type', q.category || q.type)}
                        ${V('Unit of Measurement', q.unit)}
                    </div>
                </div>

                <div class="print-section"><div class="ps-title">Identification and Sourcing</div>
                    <div class="detail-grid">
                        ${V('Brand', q.brand)}
                        ${V('Model', q.model)}
                        ${V('Serial No.', q.serial)}
                        ${V('Supplier', q.supplier)}
                        ${V('Reference Rate', q.rate ? '₱' + fmtMoney(parseFloat(q.rate) || 0) + (q.unit ? ' / ' + e(q.unit) : '') : '')}
                    </div>
                </div>

                <div class="print-section"><div class="ps-title">Specifications and Condition</div>
                    <div class="detail-grid">
                        ${V('Capacity', q.capacity)}
                        ${V('Power Source', q.powerSource)}
                        ${V('Ownership', q.ownership)}
                        ${V('Acquisition Date', q.acquisitionDate)}
                        ${V('Condition', q.condition)}
                    </div>
                </div>

                <div class="print-section"><div class="ps-title">Additional Information</div>
                    <div class="detail-grid">
                        ${V('Operating Manual', q.manual, true)}
                        ${V('Notes / Remarks', q.notes, true)}
                        ${V('Status', q.status)}
                        ${V('Requested By', q.requestedBy)}
                    </div>
                </div>

                ${AttachmentGallery.render(q.docsJSON, 'Supporting documents')}

                <div class="print-actions">
                    <button class="btn-primary" onclick="PrintDoc.print()">${Icon.printer({size:14})} Print</button>
                    <button class="btn-ghost" onclick="EquipPrintModal.close()">Close</button>
                </div>`;
    }
};

// ─── SOW BREAKDOWN MODAL ───────────────────────────────────────

const SOWBreakdownModal = {
    open(sowId, estimatesData) {
        const modal = document.getElementById('sowBreakdownModal');
        const body = document.getElementById('sowBreakdownBody');
        body.innerHTML = this.renderBreakdown(sowId, estimatesData);
        modal.classList.add('open');
        document.body.style.overflow = 'hidden';
    },
    close() {
        document.getElementById('sowBreakdownModal').classList.remove('open');
        document.body.style.overflow = '';
    },
    renderBreakdown(sowId, data) {
        let materials = [],
            equipment = [],
            labor = [],
            indirect = [];
        if (data.groups) {
            const group = data.groups.find(g => g.sowId === sowId);
            if (group) {
                materials = group.materials || [];
                equipment = group.equipment || [];
                labor = group.labor || [];
                indirect = group.indirect || [];
            }
        } else {
            materials = (data.materials || []).filter(m => m.sow === sowId);
            equipment = (data.equipment || []).filter(e => e.sow === sowId);
            labor = (data.labor || []).filter(l => l.sow === sowId);
            indirect = (data.indirect || []).filter(i => i.sow === sowId);
        }

        const matTotal = materials.reduce((s, m) => s + (parseFloat(m.cost) || 0), 0);
        const eqTotal = equipment.reduce((s, e) => s + (parseFloat(e.cost) || 0), 0);
        const laborTotal = labor.reduce((s, l) => s + (parseFloat(l.cost) || 0), 0);
        const indirectTotal = indirect.reduce((s, i) => s + (parseFloat(i.amount) || 0), 0);
        const grandTotal = matTotal + eqTotal + laborTotal + indirectTotal;

        let html = `
                <div class="print-header">
                    <h2>${sowId} — Breakdown</h2>
                    <div class="print-mono" style="font-family:'IBM Plex Mono',monospace;font-size:13px;color:var(--ink-soft);">Total Estimate: ₱${fmtMoney(grandTotal)}</div>
                </div>

                <div class="bm-summary">
                    <div class="bm-card"><div class="bm-label">Materials</div><div class="bm-value">₱${fmtMoney(matTotal)}</div></div>
                    <div class="bm-card"><div class="bm-label">Equipment</div><div class="bm-value">₱${fmtMoney(eqTotal)}</div></div>
                    <div class="bm-card"><div class="bm-label">Manpower</div><div class="bm-value">₱${fmtMoney(laborTotal)}</div></div>
                    <div class="bm-card"><div class="bm-label">Indirect Costs</div><div class="bm-value">₱${fmtMoney(indirectTotal)}</div></div>
                </div>

                <div class="print-section"><div class="ps-title">BOM (Materials)</div>
                    ${materials.length ? `<table class="ps-table"><thead><tr><th>Material</th><th>Description</th><th style="text-align:right">Qty</th><th style="text-align:right">Rate</th><th style="text-align:right">Cost</th></tr></thead><tbody>${materials.map(m => `<tr><td>${m.materialName || m.material}</td><td>${m.desc || '—'}</td><td style="text-align:right">${m.qty}</td><td style="text-align:right">₱${fmtMoney(parseFloat(m.rate || 0))}</td><td style="text-align:right">₱${fmtMoney(parseFloat(m.cost || 0))}</td></tr>`).join('')}</tbody></table>` : `<p style="font-size:12px;color:var(--ink-soft);">No materials assigned.</p>`}
                </div>

                <div class="print-section"><div class="ps-title">Equipment Needed</div>
                    ${equipment.length ? `<table class="ps-table"><thead><tr><th>Equipment</th><th>Description</th><th style="text-align:right">Qty</th><th style="text-align:right">Duration</th><th style="text-align:right">Rate</th><th style="text-align:right">Cost</th></tr></thead><tbody>${equipment.map(e => `<tr><td>${e.equipName || e.equipment}</td><td>${e.desc || '—'}</td><td style="text-align:right">${e.qty}</td><td style="text-align:right">${e.duration}</td><td style="text-align:right">₱${fmtMoney(parseFloat(e.rate || 0))}</td><td style="text-align:right">₱${fmtMoney(parseFloat(e.cost || 0))}</td></tr>`).join('')}</tbody></table>` : `<p style="font-size:12px;color:var(--ink-soft);">No equipment assigned.</p>`}
                </div>

                <div class="print-section"><div class="ps-title">Manpower</div>
                    ${labor.length ? `<table class="ps-table"><thead><tr><th>Role</th><th>Description</th><th style="text-align:right">Qty</th><th style="text-align:right">Duration</th><th style="text-align:right">Rate</th><th style="text-align:right">Cost</th></tr></thead><tbody>${labor.map(l => `<tr><td>${l.role}</td><td>${l.desc || '—'}</td><td style="text-align:right">${l.qty}</td><td style="text-align:right">${l.duration}</td><td style="text-align:right">₱${fmtMoney(parseFloat(l.rate || 0))}</td><td style="text-align:right">₱${fmtMoney(parseFloat(l.cost || 0))}</td></tr>`).join('')}</tbody></table>` : `<p style="font-size:12px;color:var(--ink-soft);">No manpower assigned.</p>`}
                </div>

                <div class="print-section"><div class="ps-title">Indirect Costs</div>
                    ${indirect.length ? `<table class="ps-table"><thead><tr><th>Description</th><th>Type</th><th style="text-align:right">Amount</th></tr></thead><tbody>${indirect.map(i => `<tr><td>${i.desc || '—'}</td><td>${i.type || '—'}</td><td style="text-align:right">₱${fmtMoney(parseFloat(i.amount || 0))}</td></tr>`).join('')}</tbody></table>` : `<p style="font-size:12px;color:var(--ink-soft);">No indirect costs assigned.</p>`}
                </div>

                <div class="print-actions">
                    <button class="btn-primary" onclick="PrintDoc.print()">${Icon.printer({size:14})} Print</button>
                    <button class="btn-ghost" onclick="SOWBreakdownModal.close()">Close</button>
                </div>`;
        return html;
    }
};
// ─── SEARCH DETAIL MODAL (v8) ──────────────────────────────────
//  Generic detail view for a global-search result: renders the
//  key/value `detail` payload the backend attached to the result.
//  Materials/Equipment usually route to their own datasheet modals
//  instead (see SearchPage.open); this is the catch-all.

const SearchDetailModal = {
    open(result) {
        const existing = document.getElementById('searchDetailModal');
        if (existing) existing.remove();
        const detail = result.detail || {};
        const overlay = document.createElement('div');
        overlay.id = 'searchDetailModal';
        overlay.className = 'print-modal-overlay open';
        overlay.innerHTML = `
            <div class="print-modal-content" style="max-width:560px;">
                <button class="close-modal" onclick="document.getElementById('searchDetailModal').remove();document.body.style.overflow='';">${Icon.close({size:18})}</button>
                <div class="print-header">
                    <h2>${result.type} — ${result.id}</h2>
                    <div class="print-meta">${result.label || ''}</div>
                </div>
                ${result.image ? `<div style="text-align:center;margin-bottom:14px;"><img src="${driveImgSrc(result.image)}" alt="" style="max-width:100%;max-height:220px;border-radius:8px;border:1px solid var(--line);" onerror="this.style.display='none'" /></div>` : ''}
                <div class="print-section"><div class="ps-title">Details</div>
                    <div class="detail-grid">
                        ${Object.keys(detail).map(k => `
                            <div class="dg-item ${String(detail[k]).length > 40 ? 'full' : ''}">
                                <span class="dg-label">${k}</span>
                                <span class="dg-value">${detail[k]}</span>
                            </div>`).join('')}
                    </div>
                </div>
                <div class="print-actions">
                    <button class="btn-ghost" onclick="document.getElementById('searchDetailModal').remove();document.body.style.overflow='';">Close</button>
                </div>
            </div>`;
        overlay.addEventListener('click', e => {
            if (e.target === overlay) { overlay.remove(); document.body.style.overflow = ''; }
        });
        document.body.appendChild(overlay);
        document.body.style.overflow = 'hidden';
    }
};

// ─── ATTACHMENT GALLERY (v10) ──────────────────────────────────
/**
 * AttachmentGallery — the single component every modal uses to show
 * files that were attached to a record.
 *
 * WHY IT EXISTS: request modals previously listed attachments as plain
 * text links, so an approver could not see a receipt without opening a
 * new tab — and in practice approved without looking. (The links were
 * often missing entirely, because the row carries `attachmentsJSON` as
 * a string while the modal looked for a parsed `attachments` array.)
 *
 * Usage:  AttachmentGallery.render(list, 'Attachments')
 *   list: [{ url, name }] — or a JSON string, or a single URL string.
 * Images render as thumbnails that open in a lightbox; anything else
 * (PDF, DWG) becomes a labelled card that opens in a new tab. A URL
 * that fails to load collapses to a caption instead of a broken box.
 */
const AttachmentGallery = {
    _items: [],

    /** normalize — accepts an array, a JSON string, or a bare URL. */
    normalize(input) {
        let list = [];
        if (!input) return list;
        if (typeof input === 'string') {
            const t = input.trim();
            if (t.startsWith('[')) { try { list = JSON.parse(t) || []; } catch (e) { list = []; } }
            else if (t) list = [{ url: t, name: '' }];
        } else if (Array.isArray(input)) {
            list = input.slice();
        }
        return list
            .map(a => (typeof a === 'string' ? { url: a, name: '' } : a))
            .filter(a => a && a.url);
    },

    _isImage(a) {
        const u = String(a.url || '').toLowerCase();
        if (/\.(jpg|jpeg|png|gif|webp|bmp|heic)(\?|$)/.test(u)) return true;
        if (/\.(pdf|dwg|dxf|docx?|xlsx?|zip)(\?|$)/.test(u)) return false;
        // Drive thumbnail/uc links are images; viewer links are unknown but
        // render fine through driveImgSrc, so treat them as images.
        return u.indexOf('drive.google.com') > -1 || u.indexOf('googleusercontent') > -1;
    },

    /**
     * render(input, label) — returns HTML. Empty input returns '' so
     * callers can drop it in unconditionally.
     */
    render(input, label) {
        const list = this.normalize(input);
        if (!list.length) return '';
        this._items = list;
        const cells = list.map((a, i) => {
            const nm = String(a.name || '').replace(/"/g, '&quot;') || ('File ' + (i + 1));
            if (this._isImage(a)) {
                return `
                <button type="button" class="att-card" onclick="AttachmentGallery.open(${i})" title="${nm}">
                    <img src="${driveImgSrc(a.url)}" alt="${nm}" loading="lazy"
                        onerror="this.style.display='none';this.parentElement.querySelector('.att-fallback').style.display='flex';" />
                    <span class="att-fallback">${Icon.warning({size:15})} Preview unavailable</span>
                    <span class="att-cap">${Icon.camera({size:11})} <span>${nm}</span></span>
                </button>`;
            }
            const ext = (String(a.url).match(/\.(\w{2,4})(\?|$)/) || [, 'FILE'])[1].toUpperCase();
            return `
                <a class="att-card att-doc" href="${a.url}" target="_blank" rel="noopener" title="${nm}">
                    <span class="att-ext">${Icon.fileText({size:20})}<b>${ext}</b></span>
                    <span class="att-cap">${Icon.fileText({size:11})} <span>${nm}</span></span>
                </a>`;
        }).join('');
        return `
            <div class="att-block">
                <div class="att-label">${label || 'Attachments'} <span class="att-count">${list.length}</span></div>
                <div class="att-grid">${cells}</div>
            </div>`;
    },

    open(i) {
        const a = this._items[i];
        if (!a) return;
        // v11 BATCH H2: the lightbox used to sit at z-index 1200 while the
        // request modal sits at 2000, so an attachment opened BEHIND the
        // modal that opened it and the modal had to be closed first. The
        // stacking is fixed in CSS; this comment is here because the two
        // numbers are far apart in the codebase and easy to break again.
        this._openedFrom = document.querySelector('.print-modal-overlay.open');
        let box = document.getElementById('attLightbox');
        if (!box) {
            box = document.createElement('div');
            box.id = 'attLightbox';
            box.className = 'att-lightbox';
            // ── v11 BATCH H2 FIX: the X did not close the lightbox ──
            // The close button contains an SVG icon, so a click lands on
            // the <svg> or its <path>, never on the button itself.
            // `e.target.dataset.close` was therefore always undefined and
            // only Escape or an outside click worked. closest() walks up
            // from whatever was actually clicked to the element carrying
            // the marker.
            box.addEventListener('click', e => {
                if (e.target === box || (e.target.closest && e.target.closest('[data-close]'))) {
                    AttachmentGallery.close();
                }
            });
            document.body.appendChild(box);
        }
        const nm = String(a.name || 'Attachment').replace(/</g, '&lt;');
        box.innerHTML = `
            <button type="button" class="att-lb-close" data-close="1" aria-label="Close">${Icon.close({size:20})}</button>
            <div class="att-lb-frame"><img src="${driveImgSrc(a.url)}" alt="${nm}" /></div>
            <div class="att-lb-cap">${nm} · <a href="${a.url}" target="_blank" rel="noopener">Open original</a></div>`;
        box.classList.add('open');
        this._esc = e => {
            if (e.key !== 'Escape') return;
            // Stop the modal underneath from also closing on the same key.
            e.stopPropagation();
            AttachmentGallery.close();
        };
        document.addEventListener('keydown', this._esc, true);
    },

    close() {
        const box = document.getElementById('attLightbox');
        if (box) box.classList.remove('open');
        if (this._esc) document.removeEventListener('keydown', this._esc, true);
    }
};

;

/* ═══════ js/core/print-doc.js ═══════ */
// ================================================================
//  core/print-doc.js — Company letterhead for every printed document
//                      (v11 BATCH E)
//
//  THE PROBLEM. Every print in the system called window.print() on a
//  modal and produced a bare browser page. No logo, no company name, no
//  address, no TIN, no PCAB licence, no signature blocks. A client
//  receiving a cash advance form, a daily record or an SWA billing had
//  nothing on the page identifying FCTC. Worse, the header was not
//  merely missing — the company details existed NOWHERE in the codebase,
//  so there was nothing to print even if a header had been added.
//
//  THE APPROACH. Rather than rewrite each of the eight print sites to
//  build its own header, PrintDoc INJECTS a letterhead and footer into
//  whatever container is about to be printed, prints, then removes them.
//  A print site changes by exactly one call:
//
//      onclick="window.print()"   ->   onclick="PrintDoc.print()"
//
//  The document's own content is untouched. That keeps this batch small
//  and means a future template change reaches every document at once
//  instead of needing eight edits.
//
//  TWO OUTPUT PATHS, because the system prints in two different ways:
//    1. MODAL PRINTS — the content is already in the page inside a
//       .print-modal-overlay. print() injects into it.
//    2. NEW-WINDOW PRINTS — the estimate summary and DUPA build a whole
//       standalone document with window.open(). documentHTML() wraps
//       their body in the same letterhead and inlines the CSS, because a
//       popup does not inherit the parent page's stylesheet.
//
//  CACHING. The template is fetched once per session. It is needed on
//  every print and cannot change mid-session unless the Super Admin
//  edits it, and that path clears the cache explicitly.
// ================================================================

const PrintDoc = {

    _tpl: null,
    _loading: null,

    /** DEFAULTS - mirrors defaultPrintTemplate_() on the server, so a
     *  failed fetch still prints something sane rather than nothing. */
    DEFAULTS: {
        companyName: 'FCTC Construction Services',
        tagline: '', addressLine1: '', addressLine2: '',
        phone: '', email: '', website: '', tin: '', pcabLicense: '',
        logoUrl: '', logoHeight: 54, accentColor: '#24455A',
        headerLayout: 'logo-left', showLogo: true, showDivider: true,
        paperSize: 'A4', marginMm: 12,
        footerText: '', showTimestamp: true, showPreparedBy: true,
        signatories: [], watermark: ''
    },

    /** load - fetches and caches. Concurrent callers share one request. */
    async load(force) {
        if (this._tpl && !force) return this._tpl;
        if (this._loading && !force) return this._loading;
        this._loading = (async () => {
            try {
                const t = await DataService.getPrintTemplate();
                this._tpl = Object.assign({}, this.DEFAULTS, t || {});
            } catch (err) {
                // A missing letterhead must never block a print. Fall
                // back to defaults and let the document out.
                console.warn('PrintDoc: template unavailable, using defaults.', err);
                this._tpl = Object.assign({}, this.DEFAULTS);
            }
            this._loading = null;
            return this._tpl;
        })();
        return this._loading;
    },

    /** clearCache - called after the template is saved or reset. */
    clearCache() { this._tpl = null; },

    /** get - the cached template, or defaults if load() has not run. */
    get() { return this._tpl || this.DEFAULTS; },

    _esc(v) {
        return String(v == null ? '' : v)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    },

    /**
     * letterheadHTML - the header block. Three layouts, because a
     * letterhead is the one thing a company has an opinion about:
     *   logo-left    logo beside the details, the usual business form
     *   logo-center  logo above centred details, for formal issues
     *   minimal      a single rule with the name and page title only
     */
    letterheadHTML(opts) {
        opts = opts || {};
        const t = this.get();
        const e = this._esc.bind(this);

        const contact = [
            t.addressLine1, t.addressLine2,
            [t.phone, t.email].filter(Boolean).join('  ·  '),
            t.website,
            [t.tin ? 'TIN: ' + t.tin : '', t.pcabLicense ? 'PCAB: ' + t.pcabLicense : '']
                .filter(Boolean).join('  ·  ')
        ].filter(Boolean).map(l => `<div class="pd-line">${e(l)}</div>`).join('');

        const logo = (t.showLogo && t.logoUrl)
            ? `<img class="pd-logo" src="${e(t.logoUrl)}" alt="" style="height:${parseInt(t.logoHeight, 10) || 54}px" />`
            : '';

        const name = `<div class="pd-name">${e(t.companyName)}</div>` +
            (t.tagline ? `<div class="pd-tagline">${e(t.tagline)}</div>` : '');

        const docTitle = opts.title
            ? `<div class="pd-doctitle">${e(opts.title)}</div>` : '';
        // ── v27: THE META LINE UNDER THE HEADING IS GONE ──
        // It repeated what the document already says — the project name
        // and location are in the letterhead and in the body — so on
        // every printed page it was a second, smaller copy of the same
        // words directly beneath the title. Callers still pass `meta`;
        // it is simply no longer rendered, so nothing else has to change
        // and no caller can reintroduce it one document at a time.
        const docMeta = '';

        // ── v23: THE DOCUMENT TITLE MOVED OUT OF THE HEADER ──
        //
        // It sat in a right-hand block beside the company details, in a
        // fixed share of the width. A short title looked fine; a long
        // one — "Attendance — BF2/NF2 Lagoon Liner — 2026-08" — wrapped
        // to three lines, pushed the block taller than the logo, and
        // broke the alignment of the whole letterhead.
        //
        // A header should identify the COMPANY. What the document is
        // belongs above the content, on a full-width line where the
        // length of the words cannot damage anything.
        const docBlock = (docTitle || docMeta)
            ? `<div class="pd-docblock">${docTitle}${docMeta}</div>` : '';

        if (t.headerLayout === 'minimal') {
            return `<header class="pd-head pd-minimal">
                <div class="pd-name">${e(t.companyName)}</div>
            </header>${t.showDivider ? '<div class="pd-rule"></div>' : ''}${docBlock}`;
        }

        if (t.headerLayout === 'logo-center') {
            return `<header class="pd-head pd-center">
                ${logo}
                ${name}
                <div class="pd-contact">${contact}</div>
            </header>${t.showDivider ? '<div class="pd-rule"></div>' : ''}${docBlock}`;
        }

        return `<header class="pd-head pd-left">
            <div class="pd-id">${logo}<div>${name}<div class="pd-contact">${contact}</div></div></div>
        </header>${t.showDivider ? '<div class="pd-rule"></div>' : ''}${docBlock}`;
    },

    /**
     * signatureHTML - the signature blocks. Rendered only when the
     * template defines any, so a document that already has its own
     * signature row (the SWA billing does) is not given a second one.
     */
    signatureHTML() {
        const t = this.get();
        const list = Array.isArray(t.signatories) ? t.signatories.filter(s => s && s.label) : [];
        if (!list.length) return '';
        const e = this._esc.bind(this);
        return `<div class="pd-signs" style="grid-template-columns:repeat(${list.length},1fr)">
            ${list.map(s => `<div class="pd-sign">
                <div class="pd-sign-line">${e(s.name) || '&nbsp;'}</div>
                <div class="pd-sign-label">${e(s.label)}</div>
                ${s.position ? `<div class="pd-sign-pos">${e(s.position)}</div>` : ''}
            </div>`).join('')}
        </div>`;
    },

    /**
     * footerHTML - printed once, at the end of the document.
     *
     * v11 BATCH H1: this used `position: fixed` so Chrome would repeat
     * it on every page. That also contributed to spurious blank pages,
     * and a footer that repeats is worth a great deal less than a
     * document that prints without a blank sheet in front of it.
     */
    footerHTML() {
        const t = this.get();
        const e = this._esc.bind(this);
        const bits = [];
        if (t.footerText) bits.push(e(t.footerText));
        if (t.showPreparedBy) {
            const u = (typeof App !== 'undefined' && App.getUser && App.getUser()) || {};
            if (u.name || u.email) bits.push('Prepared by ' + e(u.name || u.email));
        }
        if (t.showTimestamp) bits.push('Printed ' + new Date().toLocaleString());
        if (!bits.length) return '';
        return `<footer class="pd-foot">${bits.join('  ·  ')}</footer>`;
    },

    watermarkHTML() {
        const t = this.get();
        if (!t.watermark) return '';
        return `<div class="pd-watermark">${this._esc(t.watermark)}</div>`;
    },

    /** pageStyleTag - @page size/margins and the accent colour. */
    pageStyleTag() {
        const t = this.get();
        return `<style id="pd-page-style">
            @page { size: ${t.paperSize === 'Letter' ? 'Letter' : 'A4'}; margin: ${parseInt(t.marginMm, 10) || 12}mm; }
            :root { --pd-accent: ${t.accentColor}; }
        </style>`;
    },

    /**
     * print - the modal path. Injects the letterhead, signatures,
     * footer and watermark into the container that is about to print,
     * calls the browser, then removes them so the on-screen modal is
     * unchanged. Nothing is left behind if printing is cancelled,
     * because the cleanup runs on a timer rather than waiting for an
     * afterprint event that Safari does not reliably fire.
     *
     * @param opts.container  CSS selector; defaults to the open modal
     * @param opts.title      document title shown in the letterhead
     * @param opts.meta       small line under the title
     * @param opts.signatures include the signature blocks (default true)
     */
    async print(opts) {
        opts = opts || {};
        await this.load();

        const host = opts.container
            ? document.querySelector(opts.container)
            : document.querySelector('.print-modal-overlay.open .print-modal-content');

        if (!host) { window.print(); return; }

        // derive a sensible title from the document itself when the
        // caller did not pass one
        const title = opts.title !== undefined
            ? opts.title
            : (host.querySelector('.print-header h2')?.textContent || '').trim();
        const meta = opts.meta !== undefined
            ? opts.meta
            : (host.querySelector('.print-header .print-meta')?.textContent || '').trim();

        const style = document.createElement('div');
        style.innerHTML = this.pageStyleTag();
        const styleEl = style.firstElementChild;

        const head = document.createElement('div');
        head.className = 'pd-injected pd-head-wrap';
        head.innerHTML = this.watermarkHTML() + this.letterheadHTML({ title, meta });

        const tail = document.createElement('div');
        tail.className = 'pd-injected pd-tail-wrap';
        tail.innerHTML = (opts.signatures === false ? '' : this.signatureHTML()) + this.footerHTML();

        document.head.appendChild(styleEl);
        host.insertBefore(head, host.firstChild);
        host.appendChild(tail);

        const cleanup = () => {
            head.remove(); tail.remove(); styleEl.remove();
        };

        try {
            window.print();
        } finally {
            // Chrome blocks on window.print(); Safari does not. A short
            // timer covers both without depending on afterprint.
            setTimeout(cleanup, 800);
        }
    },

    /**
     * documentHTML - the new-window path. The estimate summary and DUPA
     * build a whole standalone document with window.open(), which does
     * not inherit this page's stylesheet, so the letterhead CSS has to
     * travel with them.
     *
     * @param opts.title  document title (browser tab + letterhead)
     * @param opts.meta   small line under the title
     * @param opts.body   the caller's HTML
     * @param opts.css    the caller's own extra CSS
     */
    documentHTML(opts) {
        opts = opts || {};
        const t = this.get();
        return `<!DOCTYPE html><html><head><meta charset="utf-8" />
<title>${this._esc(opts.title || t.companyName)}</title>
<link href="https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
@page { size: ${t.paperSize === 'Letter' ? 'Letter' : 'A4'}${opts.landscape ? ' landscape' : ''}; margin: ${parseInt(t.marginMm, 10) || 12}mm; }
:root { --pd-accent: ${t.accentColor}; }
body { font-family: 'Inter', Arial, sans-serif; color: #1C2321; margin: 0; padding: 22px; font-size: 12px; }
${this.baseCSS()}
${opts.css || ''}
@media print { .pd-noprint { display: none !important; } }
</style></head><body>
${this.watermarkHTML()}
${this.letterheadHTML({ title: opts.title, meta: opts.meta })}
${opts.body || ''}
${opts.signatures === false ? '' : this.signatureHTML()}
${this.footerHTML()}
<div class="pd-noprint" style="margin-top:22px;text-align:right;">
  <button onclick="window.print()" style="padding:8px 18px;font:inherit;cursor:pointer;">Print / Save as PDF</button>
</div>
</body></html>`;
    },

    /**
     * baseCSS - the letterhead styles as a string, for the new-window
     * path. The in-page path gets the same rules from print-modal.css;
     * this is the single duplicate in the module and it exists because a
     * popup genuinely cannot reach the parent's stylesheet.
     */
    baseCSS() {
        return `
.pd-head { display:flex; justify-content:space-between; align-items:flex-start; gap:20px; }
.pd-head.pd-center { flex-direction:column; align-items:center; text-align:center; gap:4px; }
.pd-head.pd-minimal { align-items:baseline; }
.pd-id { display:flex; gap:14px; align-items:flex-start; }
.pd-logo { display:block; object-fit:contain; }
.pd-name { font-family:'Oswald',sans-serif; font-size:17px; font-weight:600; text-transform:uppercase; letter-spacing:.045em; color:var(--pd-accent); line-height:1.15; }
.pd-tagline { font-size:10.5px; color:#5B6360; font-style:italic; margin-top:1px; }
.pd-contact { margin-top:4px; font-size:10px; color:#5B6360; line-height:1.5; }
.pd-contact .pd-line { white-space:nowrap; }
/* v23: kept for any older markup that still emits it, but nothing does. */
.pd-right { text-align:right; }

/* The document title, full width, under the rule. Long titles now have
   the whole page to use and cannot distort the header above them. */
.pd-docblock { margin:3mm 0 4mm; }
.pd-docblock .pd-doctitle {
    text-align:left;
    font-size:14px;
    line-height:1.25;
    /* Wrapping is fine here; there is nothing beside it to disturb. */
    word-break:break-word;
}
.pd-docblock .pd-docmeta { text-align:left; margin-top:1mm; }
.pd-doctitle { font-family:'Oswald',sans-serif; font-size:13px; text-transform:uppercase; letter-spacing:.06em; color:#1C2321; }
.pd-docmeta { font-family:'IBM Plex Mono',monospace; font-size:10px; color:#5B6360; margin-top:2px; }
.pd-rule { border-bottom:2.5px solid var(--pd-accent); margin:9px 0 16px; }
.pd-signs { display:grid; gap:26px; margin-top:42px; page-break-inside:avoid; }
.pd-sign { text-align:center; }
.pd-sign-line { border-bottom:1px solid #1C2321; padding-bottom:3px; margin-bottom:5px; font-size:11.5px; font-weight:600; min-height:16px; }
.pd-sign-label { font-size:9px; text-transform:uppercase; letter-spacing:.07em; color:#5B6360; }
.pd-sign-pos { font-size:10px; color:#5B6360; margin-top:1px; }
.pd-foot { margin-top:20px; padding-top:7px; border-top:1px solid #D6D2C4; font-size:9px; color:#5B6360; text-align:center; }
.pd-watermark { position:fixed; top:44%; left:50%; transform:translate(-50%,-50%) rotate(-32deg); font-family:'Oswald',sans-serif; font-size:88px; font-weight:600; letter-spacing:.1em; color:rgba(28,35,33,.07); pointer-events:none; z-index:0; white-space:nowrap; }
@media print { .pd-foot { position:static; background:#fff; } .pd-noprint{display:none!important;} }
`;
    }
};

;

/* ═══════ js/core/typeahead.js ═══════ */
// ================================================================
//  core/typeahead.js — Type-to-search with the match highlighted
//                      (v11 BATCH I2b)
//
//  WHY NOT A <datalist>. That is what I2 used, and it was the wrong
//  call. A datalist gives the browser complete control: no highlighting
//  of what you typed, no control over how many rows show, different
//  behaviour in every browser, and on some it will not open at all until
//  you press the down arrow. On a site form filled in at speed, that is
//  the difference between a field that helps and one that gets ignored.
//
//  This is the behaviour that worked before: type "12mm" and the list
//  shows "Rebar 12mm" with the 12mm HIGHLIGHTED, so you can see WHY each
//  row matched. Matching is on any part of the string, not just the
//  start, because nobody types a material from its first word.
//
//  FREE TEXT IS ALWAYS ALLOWED. The catalogue is a convenience, never a
//  gate — a new hire or a one-off delivery has to be enterable, and a
//  picker that refuses unknown values is how records stop being kept.
//
//  Keyboard: arrows move, Enter picks, Escape closes without changing
//  what you typed.
// ================================================================

const Typeahead = {

    _open: null,
    _items: [],
    _active: -1,
    _input: null,

    _esc(v) {
        return String(v == null ? '' : v)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    },

    /** _mark - wraps every occurrence of the typed text in <mark>. */
    _mark(text, q) {
        const t = String(text == null ? '' : text);
        if (!q) return this._esc(t);
        const lower = t.toLowerCase();
        const needle = q.toLowerCase();
        let out = '', i = 0;
        while (i < t.length) {
            const at = lower.indexOf(needle, i);
            if (at === -1) { out += this._esc(t.slice(i)); break; }
            out += this._esc(t.slice(i, at)) +
                   '<mark>' + this._esc(t.slice(at, at + needle.length)) + '</mark>';
            i = at + needle.length;
        }
        return out;
    },

    /**
     * attach - wires an input to a source of suggestions.
     *
     * @param input   the <input>
     * @param source  () => [{ label, sub, value, data }]  (or plain strings)
     * @param onPick  (item) => void, after a suggestion is chosen
     *
     * The source is a FUNCTION, not an array, so a list that grows while
     * the form is open — a material added in another tab, a person added
     * mid-session — is picked up without rewiring anything.
     */
    attach(input, source, onPick) {
        if (!input || input._taWired) return;
        input._taWired = true;
        input.setAttribute('autocomplete', 'off');
        input.addEventListener('input', () => this._show(input, source, onPick));
        input.addEventListener('focus', () => this._show(input, source, onPick));
        input.addEventListener('keydown', e => this._key(e, input, source, onPick));
        input.addEventListener('blur', () => {
            // A click on a suggestion fires blur before the click lands,
            // so the close is deferred just long enough for it to arrive.
            setTimeout(() => this.close(), 160);
        });
    },

    _normalise(list) {
        return (list || []).map(x => typeof x === 'string'
            ? { label: x, sub: '', value: x, data: null }
            : { label: x.label || x.value || '', sub: x.sub || '', value: x.value !== undefined ? x.value : (x.label || ''), data: x.data || x });
    },

    _show(input, source, onPick) {
        const q = String(input.value || '').trim();
        const all = this._normalise(typeof source === 'function' ? source() : source);

        // Anywhere in the string, not just the start — nobody types a
        // material from its first word. "12mm" has to find "Rebar 12mm".
        const hits = q
            ? all.filter(x => (x.label + ' ' + x.sub).toLowerCase().indexOf(q.toLowerCase()) > -1)
            : all;

        if (!hits.length) { this.close(); return; }

        this._items = hits.slice(0, 12);   // more than a dozen is a list, not a suggestion
        this._active = -1;
        this._input = input;

        let box = this._open;
        if (!box) {
            box = document.createElement('div');
            box.className = 'ta-box';
            document.body.appendChild(box);
            this._open = box;
        }
        box.innerHTML = this._items.map((x, i) => `
            <div class="ta-item" data-i="${i}">
                <span class="ta-label">${this._mark(x.label, q)}</span>
                ${x.sub ? `<span class="ta-sub">${this._mark(x.sub, q)}</span>` : ''}
            </div>`).join('');

        Array.from(box.querySelectorAll('.ta-item')).forEach(el => {
            // mousedown, not click: it fires before blur, so the pick is
            // not lost to the input closing first.
            el.addEventListener('mousedown', ev => {
                ev.preventDefault();
                this._pick(parseInt(el.dataset.i, 10), onPick);
            });
        });

        const r = input.getBoundingClientRect();
        box.style.left = (r.left + window.scrollX) + 'px';
        box.style.top = (r.bottom + window.scrollY + 2) + 'px';
        box.style.minWidth = r.width + 'px';
        box.style.display = 'block';
    },

    _key(e, input, source, onPick) {
        if (!this._open || this._open.style.display === 'none') {
            if (e.key === 'ArrowDown') this._show(input, source, onPick);
            return;
        }
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
            e.preventDefault();
            const n = this._items.length;
            this._active = e.key === 'ArrowDown'
                ? (this._active + 1) % n
                : (this._active - 1 + n) % n;
            Array.from(this._open.querySelectorAll('.ta-item')).forEach((el, i) =>
                el.classList.toggle('is-active', i === this._active));
        } else if (e.key === 'Enter') {
            if (this._active > -1) { e.preventDefault(); this._pick(this._active, onPick); }
        } else if (e.key === 'Escape') {
            // Closes without changing what was typed — a picker that
            // overwrites your text on Escape is worse than no picker.
            this.close();
        }
    },

    _pick(i, onPick) {
        const item = this._items[i];
        if (!item || !this._input) return;
        this._input.value = item.value;
        this._input.dispatchEvent(new Event('input', { bubbles: true }));
        this._input.dispatchEvent(new Event('change', { bubbles: true }));
        if (onPick) onPick(item, this._input);
        this.close();
    },

    close() {
        if (this._open) this._open.style.display = 'none';
        this._items = [];
        this._active = -1;
    }
};

// Reposition rather than leave a suggestion box floating over the wrong
// field when the page moves underneath it.
window.addEventListener('scroll', () => Typeahead.close(), true);
window.addEventListener('resize', () => Typeahead.close());

;

/* ═══════ js/core/signature.js ═══════ */
// ================================================================
//  core/signature.js — Turning a photographed signature into one
//                      that can sit on a document. (v13)
//
//  THE PROBLEM. A signature is signed on paper and photographed. That
//  photo is a white rectangle with some ink in it. Dropped onto a
//  report it covers whatever is underneath — a signature line, a table
//  border — with a white box, and it looks pasted on, because it is.
//
//  WHAT THIS DOES. Removes the paper and keeps the ink: every pixel
//  bright enough to be paper becomes transparent, and what remains is
//  cropped to the ink and darkened so a grey phone photo prints black.
//
//  ── WHY THRESHOLD AND NOT SOMETHING CLEVERER ─────────────────
//
//  A brightness threshold is crude. It is also the only approach that
//  behaves predictably on a photo taken on a site office desk with a
//  window on one side — anything adaptive produces a different result
//  each time and gives a person no way to understand what went wrong.
//  When it fails here, it fails visibly and the fix is obvious: better
//  light, or move the threshold slider.
//
//  Everything runs IN THE BROWSER, on a canvas. Nothing is uploaded
//  until the person can see the result, so a bad photo is discarded
//  before it becomes a record rather than after.
// ================================================================

const Signature = {

    /** Pixels brighter than this are treated as paper. */
    DEFAULT_THRESHOLD: 200,

    /**
     * process - file in, transparent PNG data URL out.
     *
     * @param file        the uploaded image
     * @param threshold   0-255; higher keeps more of the faint strokes
     * @returns { dataUrl, width, height, inkPixels }
     */
    async process(file, threshold) {
        const t = threshold === undefined ? this.DEFAULT_THRESHOLD : threshold;
        const img = await this._load(file);

        // A signature never needs to be huge, and a 12-megapixel phone
        // photo makes every document that carries it slow to open.
        const MAX_W = 900;
        const scale = img.width > MAX_W ? MAX_W / img.width : 1;
        const w = Math.round(img.width * scale);
        const h = Math.round(img.height * scale);

        const c = document.createElement('canvas');
        c.width = w; c.height = h;
        const ctx = c.getContext('2d', { willReadFrequently: true });
        ctx.drawImage(img, 0, 0, w, h);

        const data = ctx.getImageData(0, 0, w, h);
        const px = data.data;

        let minX = w, minY = h, maxX = -1, maxY = -1, ink = 0;

        for (let i = 0; i < px.length; i += 4) {
            // Perceptual brightness, not a plain average: blue ink on
            // white reads far darker to the eye than its average
            // suggests, and averaging loses it at the same threshold
            // that keeps black ink.
            const lum = 0.299 * px[i] + 0.587 * px[i + 1] + 0.114 * px[i + 2];

            if (lum >= t) {
                px[i + 3] = 0;                     // paper → transparent
                continue;
            }

            // Ink. Darken it towards black so a grey phone photo still
            // prints as a signature rather than a smudge, and fade the
            // edge pixels so the stroke does not come out jagged.
            const strength = 1 - (lum / t);        // 0 at the threshold, 1 at pure black
            px[i] = px[i + 1] = px[i + 2] = 0;
            px[i + 3] = Math.round(255 * Math.min(1, strength * 1.6));

            if (px[i + 3] > 40) {
                ink++;
                const p = i / 4;
                const x = p % w, y = (p / w) | 0;
                if (x < minX) minX = x;
                if (x > maxX) maxX = x;
                if (y < minY) minY = y;
                if (y > maxY) maxY = y;
            }
        }

        ctx.putImageData(data, 0, 0);

        // Nothing dark enough to be ink. Say so rather than returning a
        // blank image that only fails later, on a printed document.
        if (maxX < 0) {
            throw new Error('No signature found in that image. It may be too faint, ' +
                'or the photo too bright — try again with more even light.');
        }

        // Crop to the ink with a small margin. Without this the
        // signature inherits however much desk was in the photo, and two
        // signatures on one page come out at wildly different sizes.
        const pad = 8;
        const cx = Math.max(0, minX - pad);
        const cy = Math.max(0, minY - pad);
        const cw = Math.min(w, maxX + pad) - cx;
        const ch = Math.min(h, maxY + pad) - cy;

        const out = document.createElement('canvas');
        out.width = cw; out.height = ch;
        out.getContext('2d').drawImage(c, cx, cy, cw, ch, 0, 0, cw, ch);

        return {
            dataUrl: out.toDataURL('image/png'),   // PNG: JPEG has no transparency
            width: cw, height: ch, inkPixels: ink
        };
    },

    _load(file) {
        return new Promise((resolve, reject) => {
            const r = new FileReader();
            r.onload = e => {
                const img = new Image();
                img.onload = () => resolve(img);
                img.onerror = () => reject(new Error('That file could not be read as an image.'));
                img.src = e.target.result;
            };
            r.onerror = () => reject(new Error('That file could not be read.'));
            r.readAsDataURL(file);
        });
    },

    /**
     * dataUrlToBase64 - strips the prefix for the upload endpoint,
     * which expects raw base64.
     */
    dataUrlToBase64(dataUrl) {
        return String(dataUrl || '').split(',')[1] || '';
    }
};

;

/* ═══════ js/core/discussion.js ═══════ */
// ================================================================
//  core/discussion.js — A conversation attached to a record. (v14)
//
//  ONE COMPONENT, SIXTEEN PLACES.
//
//      Discussion.mount(container, 'PurchaseRequest', 'PR-2026-0042')
//
//  A thread is identified by recordType + recordId and nothing else, so
//  the code that draws one on a billing is the code that draws one on a
//  daily site record. Sixteen separate implementations would drift
//  apart within a month; this cannot.
//
//  ── WHY IT LOADS THE WAY IT DOES ─────────────────────────────
//
//  The thread is fetched ONLY when the record is opened. There is no
//  polling here — that would burn the Apps Script quota this system
//  runs on. The bell polls a single number instead; see nav.js.
//
//  A posted comment appears IMMEDIATELY, before the server confirms.
//  On Apps Script a round trip is a second or more, and a comment box
//  that sits there doing nothing after you press send gets pressed
//  again. If the save fails the comment is marked and can be retried,
//  which is honest — pretending it saved would be worse.
// ================================================================

const Discussion = {

    _people: null,        // cached for the session; the user list rarely changes
    _mentionOpen: false,

    _esc(v) {
        return String(v == null ? '' : v)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    },

    _when(v) {
        const d = new Date(v);
        if (isNaN(d)) return '';
        const mins = Math.round((Date.now() - d) / 60000);
        // Relative for anything today, absolute after that. "3 days ago"
        // is harder to reason about than a date once you are looking
        // back at a record rather than following a conversation.
        if (mins < 1) return 'just now';
        if (mins < 60) return mins + ' min ago';
        if (mins < 1440) return Math.round(mins / 60) + ' h ago';
        return d.toLocaleDateString('en-US', { day: '2-digit', month: 'short' }) +
               ' ' + d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
    },

    _initials(name) {
        return String(name || '?').trim().split(/\s+/).slice(0, 2)
            .map(w => w[0]).join('').toUpperCase();
    },

    async _loadPeople() {
        if (this._people) return this._people;
        try {
            const home = await DataService.getHomeData();
            this._people = (home && home.users) || [];
        } catch (err) { this._people = []; }
        return this._people;
    },

    /**
     * mount - draws a thread into a container.
     *
     * @param el          the element to fill
     * @param recordType  'PurchaseRequest', 'Billing', 'DailyRecord', ...
     * @param recordId    the record's own id
     * @param opts        { projectId, title }
     */
    async mount(el, recordType, recordId, opts) {
        if (!el || !recordType || !recordId) return;
        opts = opts || {};
        el.dataset.dType = recordType;
        el.dataset.dId = recordId;
        el.dataset.dProject = opts.projectId || '';

        el.innerHTML = `<div class="dsc">
            <div class="dsc-head">${Icon.messageSquare ? Icon.messageSquare({size:13}) : '💬'}
                <b>Discussion</b><span class="dsc-count">loading…</span></div>
            <div class="dsc-list"><div class="dsc-empty">Loading…</div></div>
        </div>`;

        await this._loadPeople();
        await this.refresh(el);
    },

    async refresh(el) {
        const type = el.dataset.dType, id = el.dataset.dId;
        let rows = [];
        try {
            rows = await DataService.getThread(type, id);
        } catch (err) {
            el.querySelector('.dsc-list').innerHTML =
                `<div class="dsc-empty">Could not load the discussion: ${this._esc(err.message)}</div>`;
            return;
        }
        this._paint(el, rows);
    },

    _paint(el, rows) {
        const e = this._esc.bind(this);
        const live = rows.filter(r => !r.deleted).length;

        el.innerHTML = `<div class="dsc">
            <div class="dsc-head">${Icon.messageSquare ? Icon.messageSquare({size:13}) : '💬'}
                <b>Discussion</b>
                <span class="dsc-count">${live ? live + (live === 1 ? ' comment' : ' comments') : 'no comments yet'}</span>
            </div>

            <div class="dsc-list">
                ${rows.length ? rows.map(r => this._msg(r)).join('') : `
                    <div class="dsc-empty">Nothing here yet. Anything written on this record stays
                    with it — including for whoever opens it next year.</div>`}
            </div>

            <div class="dsc-compose pd-noprint">
                <textarea class="dsc-input" rows="2"
                    placeholder="Write a comment. Type @ to mention someone."
                    oninput="Discussion.onType(this)"
                    onkeydown="Discussion.onKey(event, this)"></textarea>
                <div class="dsc-actions">
                    <label class="dsc-attach" title="Attach a file">
                        ${Icon.paperclip ? Icon.paperclip({size:14}) : '📎'}
                        <input type="file" onchange="Discussion.onFile(this)" />
                        <span class="dsc-fname"></span>
                    </label>
                    <span class="dsc-hint">Ctrl + Enter to send</span>
                    <button class="btn-sm primary" onclick="Discussion.send(this)">Send</button>
                </div>
                <div class="dsc-mentions" hidden></div>
            </div>
        </div>`;
    },

    _msg(r) {
        const e = this._esc.bind(this);
        if (r.deleted) {
            return `<div class="dsc-msg is-gone">
                <span class="dsc-av">–</span>
                <div class="dsc-body"><em>Comment deleted</em></div>
            </div>`;
        }
        const canEdit = r.isMine &&
            ((Date.now() - new Date(r.createdAt)) / 60000) < 15;
        const canDelete = r.isMine || (App.getUser() || {}).role === 'superadmin';

        return `<div class="dsc-msg" data-id="${e(r.id)}">
            <span class="dsc-av">${e(this._initials(r.authorName))}</span>
            <div class="dsc-body">
                <div class="dsc-who">${e(r.authorName)}
                    <time>${e(this._when(r.createdAt))}${r.editedAt ? ' · edited' : ''}</time>
                    <span class="dsc-tools pd-noprint">
                        ${canEdit ? `<button onclick="Discussion.startEdit('${e(r.id)}')" title="Edit">${Icon.pencil({size:11})}</button>` : ''}
                        ${canDelete ? `<button onclick="Discussion.remove('${e(r.id)}')" title="Delete">${Icon.trash({size:11})}</button>` : ''}
                    </span>
                </div>
                <p class="dsc-text">${this._render(r.body)}</p>
                ${r.attachmentUrl ? `<a class="dsc-file" href="${e(r.attachmentUrl)}" target="_blank" rel="noopener">
                    ${Icon.paperclip ? Icon.paperclip({size:11}) : '📎'} ${e(r.attachmentName || 'attachment')}</a>` : ''}
            </div>
        </div>`;
    },

    /**
     * _render - escapes first, then highlights mentions.
     *
     * The order matters: highlighting before escaping would let someone
     * write markup into a comment and have it run.
     */
    _render(body) {
        const safe = this._esc(body);
        const known = (this._people || []).map(p => String(p.email || '').toLowerCase());
        return safe
            .replace(/@([\w.+-]+@[\w.-]+)/g, (m, addr) =>
                known.indexOf(addr.toLowerCase()) > -1
                    ? `<span class="dsc-mention">@${this._nameFor(addr)}</span>`
                    : m)
            .replace(/\n/g, '<br>');
    },

    _nameFor(email) {
        const p = (this._people || []).find(x =>
            String(x.email || '').toLowerCase() === String(email).toLowerCase());
        return this._esc(p ? (p.name || p.email) : email);
    },

    // ─── mentions ────────────────────────────────────────────

    onType(ta) {
        const box = ta.closest('.dsc-compose').querySelector('.dsc-mentions');
        const upto = ta.value.slice(0, ta.selectionStart);
        const m = /@([\w.+-]*)$/.exec(upto);
        if (!m) { box.hidden = true; return; }

        const q = m[1].toLowerCase();
        const hits = (this._people || [])
            .filter(p => (String(p.name || '') + ' ' + String(p.email || '')).toLowerCase().indexOf(q) > -1)
            .slice(0, 6);

        if (!hits.length) { box.hidden = true; return; }
        box.hidden = false;
        box.innerHTML = hits.map((p, i) => `
            <button class="${i === 0 ? 'is-active' : ''}"
                onmousedown="event.preventDefault();Discussion.pickMention('${this._esc(p.email)}', this)">
                <b>${this._esc(p.name || p.email)}</b><em>${this._esc(p.email)}</em>
            </button>`).join('');
    },

    pickMention(email, btn) {
        const box = btn.closest('.dsc-mentions');
        const ta = box.closest('.dsc-compose').querySelector('.dsc-input');
        const upto = ta.value.slice(0, ta.selectionStart);
        const rest = ta.value.slice(ta.selectionStart);
        ta.value = upto.replace(/@[\w.+-]*$/, '@' + email + ' ') + rest;
        box.hidden = true;
        ta.focus();
    },

    onKey(ev, ta) {
        const box = ta.closest('.dsc-compose').querySelector('.dsc-mentions');
        if (!box.hidden) {
            const btns = Array.from(box.querySelectorAll('button'));
            const cur = btns.findIndex(b => b.classList.contains('is-active'));
            if (ev.key === 'ArrowDown' || ev.key === 'ArrowUp') {
                ev.preventDefault();
                const n = ev.key === 'ArrowDown' ? (cur + 1) % btns.length
                                                 : (cur - 1 + btns.length) % btns.length;
                btns.forEach((b, i) => b.classList.toggle('is-active', i === n));
                return;
            }
            if (ev.key === 'Enter' && cur > -1) { ev.preventDefault(); btns[cur].onmousedown(new Event('x')); return; }
            if (ev.key === 'Escape') { box.hidden = true; return; }
        }
        if (ev.key === 'Enter' && (ev.ctrlKey || ev.metaKey)) {
            ev.preventDefault();
            this.send(ta.closest('.dsc-compose').querySelector('.btn-sm'));
        }
    },

    onFile(input) {
        const f = input.files && input.files[0];
        const label = input.closest('.dsc-attach').querySelector('.dsc-fname');
        label.textContent = f ? f.name : '';
    },

    // ─── posting ─────────────────────────────────────────────

    async send(btn) {
        const wrap = btn.closest('.dsc');
        const el = wrap.parentElement;
        const ta = wrap.querySelector('.dsc-input');
        const fileEl = wrap.querySelector('.dsc-attach input');
        const body = ta.value.trim();
        const file = fileEl.files && fileEl.files[0];

        if (!body && !file) { UI.toast('Write something, or attach a file.', 'error'); return; }

        const mentions = (body.match(/@([\w.+-]+@[\w.-]+)/g) || [])
            .map(m => m.slice(1).toLowerCase());

        // Drawn immediately. On Apps Script a round trip is a second or
        // more, and a box that does nothing after Send gets pressed
        // again — which is how a comment ends up posted twice.
        const user = App.getUser() || {};
        const list = wrap.querySelector('.dsc-list');
        const empty = list.querySelector('.dsc-empty');
        if (empty) empty.remove();
        const temp = document.createElement('div');
        temp.className = 'dsc-msg is-sending';
        temp.innerHTML = `<span class="dsc-av">${this._esc(this._initials(user.name))}</span>
            <div class="dsc-body">
                <div class="dsc-who">${this._esc(user.name || 'You')}<time>sending…</time></div>
                <p class="dsc-text">${this._render(body)}</p>
            </div>`;
        list.appendChild(temp);
        list.scrollTop = list.scrollHeight;
        ta.value = '';
        btn.disabled = true;

        try {
            const payload = {
                recordType: el.dataset.dType, recordId: el.dataset.dId,
                projectId: el.dataset.dProject, body: body, mentions: mentions
            };
            if (file) {
                payload.attachmentBase64 = await fileToBase64_(file);
                payload.attachmentName = file.name;
                payload.attachmentMime = file.type;
            }
            const res = await DataService.postComment(payload);
            // v28: nothing is emailed. A mention raises the mentioned
            // person's bell, so the toast says what actually happened
            // rather than promising a message that never leaves.
            if (res && res.mentioned) {
                UI.toast(`${res.mentioned} person(s) mentioned — they have been notified.`, 'success');
            }
            fileEl.value = '';
            wrap.querySelector('.dsc-fname').textContent = '';
            await this.refresh(el);
            if (typeof Nav !== 'undefined' && Nav.refreshBell) Nav.refreshBell();
        } catch (err) {
            // Marked, not silently dropped. Pretending it saved would be
            // worse than admitting it did not.
            temp.classList.remove('is-sending');
            temp.classList.add('is-failed');
            temp.querySelector('time').textContent = 'not sent';
            ta.value = body;
            UI.toast('' + err.message, 'error');
        } finally {
            btn.disabled = false;
        }
    },

    startEdit(id) {
        const msg = document.querySelector(`.dsc-msg[data-id="${id}"]`);
        if (!msg) return;
        const p = msg.querySelector('.dsc-text');
        const current = p.innerText;
        p.outerHTML = `<div class="dsc-editing">
            <textarea rows="2">${this._esc(current)}</textarea>
            <div>
                <button class="btn-sm primary" onclick="Discussion.saveEdit('${this._esc(id)}', this)">Save</button>
                <button class="btn-sm" onclick="Discussion.cancelEdit(this)">Cancel</button>
            </div>
        </div>`;
    },

    async saveEdit(id, btn) {
        const wrap = btn.closest('.dsc-editing');
        const text = wrap.querySelector('textarea').value.trim();
        const el = btn.closest('.dsc').parentElement;
        try {
            await DataService.editComment(id, text);
            await this.refresh(el);
        } catch (err) { UI.toast('' + err.message, 'error'); }
    },

    cancelEdit(btn) {
        const el = btn.closest('.dsc').parentElement;
        this.refresh(el);
    },

    async remove(id) {
        const ok = await Confirm.open('Delete this comment?',
            'It will show as deleted rather than disappearing — removing it outright would leave any reply answering nothing.');
        if (!ok) return;
        const el = document.querySelector(`.dsc-msg[data-id="${id}"]`).closest('.dsc').parentElement;
        try {
            await DataService.deleteComment(id);
            await this.refresh(el);
        } catch (err) { UI.toast('' + err.message, 'error'); }
    }
};

;

/* ═══════ js/core/nav.js ═══════ */
// ================================================================
//  core/nav.js — The grouped navigation shell (v12 CONTROL ROOM)
//
//  WHAT CHANGED AND WHY.
//
//  Every page used to render its own topbar, so the same brand block
//  and back button existed twenty-odd times and the person had no idea
//  what else the system contained until they returned home. There was
//  no sense of place: you were either on the home tiles or lost inside
//  one page.
//
//  This replaces all of that with ONE shell, rendered once:
//
//    · a top bar of six GROUPS, always visible
//    · a sub bar of the pages inside the current group
//    · a right rail on Home showing what is waiting for you
//
//  THE GROUPING IS BY WHAT THE WORK IS, not by which sheet it lives in.
//  "Money in" and "Money out" rather than one Finance bucket, because
//  everything here is finance — what a person needs at the moment they
//  are hunting for a page is which direction the money is going.
//
//  Page ids are unchanged, so every existing App.navigate() call, deep
//  link and button keeps working. This is a shell around the app, not a
//  rewrite of it.
// ================================================================

const Nav = {

    /**
     * GROUPS - the whole system, in the order it is used.
     *
     * `roles` omitted means everyone who can see the page at all. The
     * filtering still happens in App.navigate; this only decides what
     * is worth showing, so a request-only user is not given a bar full
     * of things that will refuse them.
     */
    /**
     * GROUPS - the six sections from the Control Room direction.
     *
     * Named for the DEPARTMENT the work belongs to, which is how people
     * already talk about it: "that's a procurement thing", "ask finance".
     * An earlier draft split money into "Money in" and "Money out";
     * that reads well on a nav bar but it is not how anybody refers to
     * the work, and a label you have to translate in your head is worse
     * than a familiar one.
     *
     * `roles` omitted means everyone who can reach the page at all. The
     * real gate is still App.navigate; this only decides what is worth
     * showing, so a request-only user is not handed a bar full of
     * things that will refuse them.
     */
    GROUPS: [
        {
            id: 'projects', label: 'Projects',
            pages: [
                { id: 'home', label: 'Dashboard' },
                { id: 'portfolio', label: 'Portfolio', roles: ['superadmin', 'admin', 'approver'] }
            ]
        },
        {
            id: 'finance', label: 'Finance',
            pages: [
                { id: 'finance', label: 'Overview', roles: ['superadmin', 'admin', 'approver'] },
                { id: 'request', label: 'Cash advance' },
                { id: 'liquidate', label: 'Liquidate' },
                { id: 'release-cash', label: 'Release cash', roles: ['superadmin'] },
                { id: 'record-cash', label: 'Record cash received', roles: ['superadmin', 'admin', 'approver'] },
                { id: 'payables', label: 'Payables', roles: ['superadmin', 'admin', 'approver'] }
            ]
        },
        {
            id: 'procurement', label: 'Procurement',
            pages: [
                { id: 'purchase-requests', label: 'Purchase requests' },
                { id: 'knowledge', label: 'Suppliers', tab: 'suppliers', roles: ['superadmin', 'admin', 'approver'] }
            ]
        },
        {
            id: 'commercial', label: 'Commercial',
            roles: ['superadmin', 'admin', 'approver'],
            pages: [{ id: 'quotations', label: 'Quotations' }]
        },
        {
            id: 'knowledge', label: 'Knowledge',
            pages: [
                { id: 'knowledge', label: 'Materials', tab: 'materials' },
                { id: 'knowledge', label: 'Tools & equipment', tab: 'equipment' },
                { id: 'knowledge', label: 'Manpower', tab: 'manpower' },
                // v22: Suppliers belongs here too. It was only under
                // Procurement, so the Knowledge bar showed four of the
                // five reference lists and the fifth appeared to be
                // missing.
                { id: 'knowledge', label: 'Suppliers', tab: 'suppliers',
                  roles: ['superadmin', 'admin', 'approver'] },
                { id: 'knowledge', label: 'Lessons learned', tab: 'lessons' },
                { id: 'search', label: 'Search records' }
            ]
        },
        {
            id: 'approvals', label: 'Approvals',
            pages: [
                { id: 'approvals', label: 'Waiting on you' }
            ]
        },
        {
            // v22: its own group. The print template was under Approvals,
            // where it had nothing to do with approving anything — it was
            // there because there was nowhere else to put it, and that is
            // how a Settings group ends up never existing.
            id: 'settings', label: 'Settings',
            roles: ['superadmin'],
            pages: [
                { id: 'print-template', label: 'Print template' }
            ]
        }
    ],

    _esc(v) {
        return String(v == null ? '' : v)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    },

    _allowed(entry, role) {
        return !entry.roles || entry.roles.indexOf(role) > -1;
    },

    /**
     * groupOf - which group a page belongs to, for highlighting.
     *
     * The Knowledge Base is ONE page that appears in two groups —
     * Suppliers under Procurement, Materials under Knowledge. Matching
     * on the page id alone would always return the first group found, so
     * opening Materials would light up Procurement. The tab is checked
     * first, and only then the page.
     */
    groupOf(pageId, tab) {
        if (tab) {
            for (const g of this.GROUPS) {
                if (g.pages.some(p => p.id === pageId && p.tab === tab)) return g.id;
            }
        }
        for (const g of this.GROUPS) {
            if (g.pages.some(p => p.id === pageId && !p.tab)) return g.id;
        }
        for (const g of this.GROUPS) {
            if (g.pages.some(p => p.id === pageId)) return g.id;
        }
        return null;
    },

    /**
     * render - draws the bar for the current page.
     * Called on every navigation; cheap, and it means the highlighted
     * group can never drift from where you actually are.
     */
    render(pageId, tab) {
        const host = document.getElementById('appNav');
        if (!host) return;

        const user = (typeof App !== 'undefined' && App.getUser && App.getUser()) || {};
        const role = user.role || '';
        const e = this._esc.bind(this);

        // Login and other chrome-free screens get no bar at all.
        if (!user.email || pageId === 'login') { host.innerHTML = ''; host.hidden = true; return; }
        host.hidden = false;
        setTimeout(() => this.startBell(), 400);   // v14
        this.paintBranding();

        const groups = this.GROUPS
            .filter(g => this._allowed(g, role))
            .map(g => ({ ...g, pages: g.pages.filter(p => this._allowed(p, role)) }))
            .filter(g => g.pages.length);

        // The active tab decides the group when a page lives in two.
        const activeTab = tab || (typeof KnowledgeBasePage !== 'undefined' && KnowledgeBasePage._tab) || '';
        const currentGroup = this.groupOf(pageId, activeTab) || (groups[0] && groups[0].id);
        const group = groups.find(g => g.id === currentGroup);

        // v12: the SAME logo the print template already uses. It is set
        // once, under Print template, and read here — uploading it in two
        // places is how the app and the letterhead end up different, and
        // a letterhead that does not match the app is the kind of detail
        // a client notices.
        const url = (typeof PrintDoc !== 'undefined' && PrintDoc._tpl && PrintDoc._tpl.logoUrl) || '';
        const logo = url
            ? `<img src="${e(url)}" alt="FCTC" onerror="this.replaceWith(document.createTextNode('F'))" />`
            : 'F';

        host.innerHTML = `
            <div class="nav-bar">
                <button class="nav-mark" onclick="App.navigate('home')" title="Dashboard">
                    <i>${logo}</i><span>FCTC</span>
                </button>
                <nav class="nav-groups" aria-label="Sections">
                    ${groups.map(g => `
                        <button class="${g.id === currentGroup ? 'cur' : ''}"
                                aria-current="${g.id === currentGroup ? 'page' : 'false'}"
                                onclick="Nav.goGroup('${e(g.id)}')">${e(g.label)}</button>`).join('')}
                </nav>
                <span class="nav-sp"></span>
                <button class="nav-icon" onclick="App.navigate('search')" title="Search records">${Icon.search({ size: 15 })}</button>
                <!-- v14: the bell sits beside search because that is where
                     people already look when they want to FIND something,
                     and an unread mention is a thing you are being asked
                     to find. -->
                <button class="nav-icon nav-bell" onclick="Nav.toggleBell()" title="Notifications">
                    ${Icon.bell ? Icon.bell({ size: 15 }) : '🔔'}
                    <span class="bell-dot" id="bellDot" hidden></span>
                </button>
                <div class="bell-panel" id="bellPanel" hidden></div>
                <button class="nav-icon" onclick="App.toggleTheme()" title="Light or dark">${Icon.themeToggle({ size: 15 })}</button>
                <span class="nav-who">${e(user.name || user.email)}<em>${e(this._roleLabel(role))}</em></span>
                <!-- v22: a door, not an X. An X means "close this", and
                     people pressed it expecting to dismiss something and
                     were signed out instead. It now asks first. -->
                <button class="nav-icon" onclick="Nav.confirmLogout()" title="Sign out">${Icon.logout({ size: 15 })}</button>
                <button class="nav-burger" onclick="Nav.toggleMobile()" aria-label="Menu">${Icon.menu({ size: 17 })}</button>
            </div>
            ${group ? `
            <div class="nav-sub" aria-label="${e(group.label)}">
                ${group.pages.map(p => `
                    <button class="${p.id === pageId && (!p.tab || p.tab === activeTab) ? 'cur' : ''}"
                            onclick="Nav.go('${e(p.id)}'${p.tab ? `,'${e(p.tab)}'` : ''})">${e(p.label)}</button>`).join('')}
            </div>` : ''}`;
    },

    /**
     * paintBranding - put the uploaded logo in every page's topbar mark.
     *
     * Each page's header carried a hard-coded letter "F" — fourteen of
     * them — so uploading a logo in the print template changed the
     * letterhead and the nav bar but left every page header showing a
     * letter that belonged to nobody.
     *
     * The logo replaces the boxed letter rather than sitting inside it:
     * a bordered square around someone's mark reads as a placeholder
     * that was never finished. Without a logo the lettered box stays,
     * because a header with nothing in the corner looks broken.
     */
    paintBranding() {
        const apply = (url) => {
            document.querySelectorAll('.topbar .mark').forEach((el) => {
                if (!url) {
                    // Logo cleared: put the lettered box back, or the
                    // corner is left empty.
                    if (el.dataset.logo) {
                        delete el.dataset.logo;
                        el.classList.remove('has-logo');
                        el.textContent = 'F';
                    }
                    return;
                }
                if (el.dataset.logo === url) return;   // already painted
                el.dataset.logo = url;
                el.classList.add('has-logo');
                const img = new Image();
                img.src = url;
                img.alt = '';
                // A broken link must not leave an empty corner.
                img.onerror = () => {
                    el.classList.remove('has-logo');
                    el.textContent = 'F';
                    delete el.dataset.logo;
                };
                el.textContent = '';
                el.appendChild(img);
            });
        };

        const cached = (typeof PrintDoc !== 'undefined' && PrintDoc._tpl && PrintDoc._tpl.logoUrl) || '';
        if (cached) { apply(cached); return; }
        if (typeof PrintDoc === 'undefined' || !PrintDoc.load) return;
        PrintDoc.load()
            .then((t) => apply((t && t.logoUrl) || ''))
            .catch(() => {});
    },

    _roleLabel(r) {
        return { superadmin: 'Super Admin', admin: 'Admin', approver: 'Approver',
                 'request-only': 'Requester' }[r] || r;
    },

    /** goGroup - opens a group at its first page. */
    goGroup(gid) {
        const user = (typeof App !== 'undefined' && App.getUser && App.getUser()) || {};
        const g = this.GROUPS.find(x => x.id === gid);
        if (!g) return;
        const first = g.pages.filter(p => this._allowed(p, user.role || ''))[0];
        if (first) this.go(first.id, first.tab);
    },

    go(pageId, tab) {
        this.closeMobile();
        App.navigate(pageId);
        // The Knowledge Base is one page with several tabs, so a nav
        // entry has to be able to land on a specific one.
        if (tab && typeof KnowledgeBasePage !== 'undefined' && KnowledgeBasePage.switchTab) {
            setTimeout(() => {
                KnowledgeBasePage.switchTab(tab);
                // Redraw so the bar follows the tab that was just opened.
                this.render(pageId, tab);
            }, 40);
        }
    },

    // ── NOTIFICATIONS ───────────────────────────────────────
    //
    // You are notified about three things: a comment that names you, a
    // comment on a request you submitted, and a task assigned to you.
    // Everything else on a thread is somebody else's conversation.
    //
    // Nothing is emailed. The bell is the only channel, which is why it
    // has to be prompt.
    //
    // HOW FRESH IT ACTUALLY IS: this polls. On D1 a poll is cheap enough
    // to run every 30 seconds — the old 90 was sized for the Apps Script
    // quota that no longer applies. It also refreshes the moment you
    // return to the tab and immediately after you post a comment, so in
    // normal use it is current; between those, it can be up to 30
    // seconds behind. Calling that "real time" would be a promise the
    // transport does not keep.
    //
    // Polling stops when the tab is hidden. A laptop left open on a
    // desk overnight would otherwise spend the night asking.

    _bellTimer: null,
    _unread: null,

    startBell() {
        if (this._bellTimer) return;
        const tick = () => {
            if (document.hidden) return;
            this.refreshBell();
        };
        // v25: the FIRST poll is delayed by 2.5 seconds. It used to fire
        // during page load, adding one more request to the handful
        // already competing for the backend — and an unread count is not
        // urgent enough to justify making the page people are waiting
        // for any slower.
        setTimeout(tick, 2500);
        this._bellTimer = setInterval(tick, 30000);
        // Catch up the moment you come back rather than waiting out the
        // rest of the interval.
        document.addEventListener('visibilitychange', () => {
            if (!document.hidden) this.refreshBell();
        });
    },

    async refreshBell() {
        try {
            this._unread = await DataService.getUnread();
        } catch (err) { return; }   // never let the badge break the page
        const dot = document.getElementById('bellDot');
        if (!dot) return;
        const n = (this._unread && this._unread.total) || 0;
        dot.hidden = n === 0;
        dot.textContent = n > 9 ? '9+' : String(n);
        // A mention is addressed to you by name; being copied in is not
        // the same thing, and the colour says which it is.
        dot.classList.toggle('is-mention', !!(this._unread && this._unread.mentions));
        const panel = document.getElementById('bellPanel');
        if (panel && !panel.hidden) this._paintBell();
    },

    toggleBell() {
        const panel = document.getElementById('bellPanel');
        if (!panel) return;
        panel.hidden = !panel.hidden;
        if (!panel.hidden) { this._paintBell(); this.refreshBell(); }
    },

    _paintBell() {
        const panel = document.getElementById('bellPanel');
        const u = this._unread || { total: 0, items: [] };
        const e = this._esc.bind(this);
        const label = t => String(t).replace(/([A-Z])/g, ' $1').trim();

        panel.innerHTML = `
            <div class="bell-head">
                <b>Notifications</b>
                ${u.total ? `<button onclick="Nav.clearBell()">Mark all read</button>` : ''}
            </div>
            ${u.items && u.items.length ? u.items.map(i => `
                <button class="bell-item ${i.mentioned ? 'is-mention' : ''} ${i.read ? 'is-read' : ''}"
                        onclick="Nav.openNotification('${e(i.recordType)}','${e(i.recordId)}','${e(i.projectId)}')">
                    <span class="bi-top">
                        ${i.read ? '' : '<span class="bi-new"></span>'}
                        ${i.mentioned ? '<em>mentioned you</em>' : ''}
                        <b>${e(i.authorName)}</b>
                        <span>${e(label(i.recordType))} ${e(i.recordId)}</span>
                    </span>
                    <span class="bi-body">${e(i.excerpt)}</span>
                </button>`).join('')
            : '<div class="bell-empty">Nothing in the last 30 days. Mentions, replies on your own requests, and tasks assigned to you show up here.</div>'}
            <div class="bell-foot">
                ${u.total ? `${u.total} unread of ${u.shown || u.items.length} shown. ` : ''}Last 30 days.</div>`;
    },

    async clearBell() {
        try {
            await DataService.markAllRead();
            await this.refreshBell();
            this._paintBell();
        } catch (err) { UI.toast('' + err.message, 'error'); }
    },

    /**
     * openNotification - takes you to the record the comment is on.
     * A notification you cannot act on is just an interruption.
     */
    openNotification(type, id, projectId) {
        document.getElementById('bellPanel').hidden = true;
        // Reading it is the acknowledgement, so the badge drops as soon
        // as you open the thing rather than waiting for "mark all read".
        if (typeof DataService !== 'undefined' && DataService.markThreadRead) {
            DataService.markThreadRead(type, id)
                .then(() => this.refreshBell())
                .catch(() => {});
        }
        // A task opens the dashboard, where the calendar it lives on is
        // mounted; there is no approvals record behind it to look up.
        if (type === 'Task') { App.navigate('home'); return; }
        const route = {
            PurchaseRequest: 'purchase-requests', PurchaseOrder: 'purchase-requests',
            Quotation: 'quotations', Billing: 'billings'
        }[type];

        if (projectId && ['DailyRecord', 'Estimate', 'SOWItem', 'Project'].indexOf(type) > -1) {
            App.navigate('project');
            setTimeout(() => ProjectPage.open(projectId), 60);
            return;
        }
        if (route) { App.navigate(route); return; }
        // Everything else lives in the approvals inbox, which already
        // opens any record type by id.
        App.navigate('approvals');
        setTimeout(() => {
            if (typeof RequestDetailModal !== 'undefined') RequestDetailModal.open(id, type);
        }, 120);
    },

    /**
     * confirmLogout (v22) - asks before ending the session.
     *
     * Signing out is cheap to undo — you log back in — but it throws
     * away whatever half-filled form was on screen, and on Apps Script
     * logging back in is one of the slowest things the system does. One
     * dialog is worth it.
     */
    async confirmLogout() {
        const ok = await Confirm.open('Sign out?',
            'Anything you have typed and not saved will be lost.');
        if (ok) App.logout();
    },

    toggleMobile() {
        document.getElementById('appNav')?.classList.toggle('open');
    },
    closeMobile() {
        document.getElementById('appNav')?.classList.remove('open');
    }
};

;

/* ═══════ js/core/config.js ═══════ */
// ================================================================
//  core/config.js — Everything that differs between companies.
//
//  ONE CODEBASE, TWO DEPLOYMENTS. The alternative — forking the repo
//  per company — looks simpler on day one and is the more expensive
//  choice by a wide margin: every fix from here on would have to be
//  applied twice, and the two copies drift apart the first time one of
//  them gets a hotfix the other does not.
//
//  So: the code is identical everywhere, and ONLY THIS FILE changes.
//  It is the single thing you edit when standing up a new company.
//
//  ── SETTING UP A SECOND COMPANY ──────────────────────────────
//
//  1. Copy the Google Sheet (File → Make a copy). Empty the data rows;
//     keep the headers. Note the new spreadsheet id from its URL.
//  2. Copy the Apps Script project, point SHEET_ID in 00-Config.gs at
//     the new sheet, and deploy it as a Web App with "Anyone" access.
//     Note the /exec URL.
//  3. Copy this file to config.js in the new deployment and change the
//     four values below.
//  4. Deploy the frontend to Cloudflare Pages.
//
//  Nothing else in the repository is company-specific. There is a test
//  that keeps it that way.
//
//  ── A NOTE ON WHAT IS AND IS NOT SECRET ──────────────────────
//
//  The API URL is NOT a secret and cannot be treated as one: it ships
//  in the browser bundle, so anyone using the app can read it. The
//  Apps Script is deployed as "Anyone" because that is what avoids the
//  CORS preflight failure — the access control is the SESSION TOKEN
//  checked on every call, not the obscurity of the URL.
//
//  The consequence worth understanding: the two companies are separated
//  by having SEPARATE SPREADSHEETS AND SEPARATE DEPLOYMENTS, not by
//  anything in this file. Never point two companies at one backend and
//  try to filter by company in the app — one missed filter and one
//  company reads the other's contracts.
// ================================================================

const CONFIG = {

    /**
     * apiUrl - the backend for THIS company.
     *
     * Now the Cloudflare Worker in front of the teem-db D1 database. The
     * Apps Script deployment this used to point at still exists, but its
     * only remaining job is proxying uploads to Drive — a Worker cannot
     * write to Drive on its own, so that one task stays with the script,
     * which runs as you and therefore owns the files it creates.
     */
    apiUrl: 'https://teeminc-wwtp-erp.f2cconstructionservice.workers.dev',

    /** company - what the app calls itself. */
    company: {
        short: 'TEEM',
        name: 'Technical Experts on Environmental Management Inc.',
        appName: 'TEEM - WWTP ERP System',
        // Shown on the login screen under the sign-in button.
        notice: 'Wastewater Treatment Plant Division ERP System'
    },

    /**
     * currency - symbol and locale. Both companies are Philippine
     * today, but a figure formatted for the wrong locale is the kind
     * of error nobody spots until a client does.
     */
    currency: { symbol: '₱', locale: 'en-PH' },

    /**
     * accent - the one accent colour. Giving each company a different
     * accent is not decoration: when you have two tabs open it is the
     * fastest way to know which company you are about to post a cash
     * advance against.
     */
    accent: null   // null keeps the stylesheet default (amber)
};

/**
 * applyConfig - writes the configured identity into the page.
 *
 * Done at runtime rather than by editing index.html per company,
 * because a second copy of the markup is a second thing to keep in
 * step — the same reason the dashboard tiles were removed.
 */
function applyConfig() {
    const c = CONFIG.company || {};

    document.title = c.appName || 'Operations Board';

    document.querySelectorAll('[data-cfg]').forEach(el => {
        const key = el.dataset.cfg;
        const val = key.split('.').reduce((o, k) => (o || {})[k], CONFIG);
        if (val !== undefined && val !== null) el.textContent = val;
    });

    if (CONFIG.accent) {
        document.documentElement.style.setProperty('--amber', CONFIG.accent);
        document.documentElement.style.setProperty('--safety', CONFIG.accent);
    }
}

if (typeof document !== 'undefined') {
    document.addEventListener('DOMContentLoaded', applyConfig);
}

;

/* ═══════ js/core/request-queue.js ═══════ */
// ================================================================
//  core/request-queue.js — One thing at a time, and try again. (v25)
//
//  ── WHAT THIS IS FOR ────────────────────────────────────────
//
//  An Apps Script web app does not answer a POST directly. It replies
//  with a 302 to script.googleusercontent.com carrying a one-time
//  token, and the browser follows it. Under concurrency that redirect
//  target sometimes returns 404 — the request was fine, the code was
//  fine, and the answer never arrives.
//
//  It is transient, it is Google's, and there is nothing in the backend
//  that can prevent it. What CAN be controlled is how many requests are
//  in the air at once, and what happens when one fails.
//
//  ── WHY IT STARTED SHOWING UP NOW ───────────────────────────
//
//  Opening the dashboard fires: the home payload, the current month,
//  two prefetched months, the notification bell, and a background
//  revalidation behind each cached read. Five or six at once, from one
//  session, to a backend that serialises per user.
//
//  Deleting a project makes it worse in the way that matters: it is the
//  longest write in the system and it holds the document lock for the
//  whole of it. Everything else queues behind it, times out at the
//  network layer, and retries into the same jam. That is why it looked
//  like the delete caused it — the delete did not break anything, it
//  just held the door.
//
//  ── THE TWO RULES ───────────────────────────────────────────
//
//  1. AT MOST TWO REQUESTS IN FLIGHT. Not one: a single lane makes the
//     app feel slower than it is, because a slow read would block a
//     fast one behind it. Two keeps the pipe busy without stampeding.
//
//  2. A FAILED READ IS RETRIED. A failed WRITE IS NOT — see below,
//     because that distinction is the whole safety of this file.
// ================================================================

const RequestQueue = {

    /** How many may be in the air at once. */
    LIMIT: 2,

    /** Retry only these. A 404 here is the redirect flake, not a missing
     *  endpoint — a genuinely wrong URL fails every time and the retries
     *  simply exhaust and report it. */
    RETRY_STATUS: { 404: 1, 429: 1, 500: 1, 502: 1, 503: 1, 504: 1 },

    /** Three attempts. Beyond that the delay a person waits is worse
     *  than the error they could have acted on a minute ago. */
    MAX_TRIES: 3,

    _active: 0,
    _waiting: [],

    /**
     * run - queues a request.
     *
     * @param fn      () => Promise, performs the fetch
     * @param opts    { retry: bool }
     */
    run(fn, opts) {
        return new Promise((resolve, reject) => {
            this._waiting.push({ fn: fn, opts: opts || {}, resolve, reject });
            this._pump();
        });
    },

    _pump() {
        while (this._active < this.LIMIT && this._waiting.length) {
            const job = this._waiting.shift();
            this._active++;
            this._attempt(job, 1);
        }
    },

    async _attempt(job, tryNo) {
        try {
            const result = await job.fn();
            this._active--;
            job.resolve(result);
            this._pump();
        } catch (err) {
            const status = err && err.httpStatus;
            const retryable = job.opts.retry &&
                tryNo < this.MAX_TRIES &&
                (this.RETRY_STATUS[status] || err.name === 'TypeError');

            if (!retryable) {
                this._active--;
                job.reject(err);
                this._pump();
                return;
            }

            // Backoff with a little randomness. Without the jitter, five
            // requests that failed together would all retry at the same
            // instant and recreate the pile-up that caused it.
            const wait = (tryNo * 700) + Math.floor(Math.random() * 400);
            setTimeout(() => this._attempt(job, tryNo + 1), wait);
        }
    },

    /** Depth, for the "still working" indicator. */
    pending() { return this._active + this._waiting.length; }
};

;

/* ═══════ js/core/fast-cache.js ═══════ */
// ================================================================
//  core/fast-cache.js — Making it FEEL instant. (v17)
//
//  ── THE DISTINCTION THAT MATTERS ────────────────────────────
//
//  Making the server faster and making the app feel faster are
//  different problems. The backend cache turns a 3-second load into
//  0.5 seconds — real, and still a wait.
//
//  This turns it into no wait at all: the last version you saw is drawn
//  IMMEDIATELY from memory, a fresh copy is fetched behind it, and the
//  screen updates only if something actually changed. Stale, then
//  revalidated.
//
//  ── WHY THIS IS SAFE IN A SYSTEM THAT HOLDS MONEY ───────────
//
//  Showing a figure that is thirty seconds old is only dangerous if the
//  person cannot tell. Three rules make it safe:
//
//  1. WRITES ARE NEVER CACHED. Only reads. Approving, releasing and
//     billing always hit the server.
//  2. A WRITE CLEARS EVERYTHING. The moment anything is submitted from
//     this browser, every cached read is dropped — so you never see
//     your own change missing, which is the failure people actually
//     notice and lose trust over.
//  3. THE REFRESH ALWAYS RUNS. Cached data is never the final answer;
//     it is what fills the screen while the real answer arrives.
//
//  Nothing is written to disk. This lives in memory for the tab's
//  lifetime, so closing the tab is a full reset and there is no stale
//  copy sitting in storage after a password change.
// ================================================================

const FastCache = {

    _mem: {},
    _inflight: {},

    /** Reads that are worth holding. Anything not listed always goes to
     *  the server — the safe default. */
    CACHEABLE: {
        getProjectDataCached: 1, getProjectData: 1,
        getHomeDataCached: 1, getHomeData: 1,
        getPortfolioDataCached: 1, getPortfolioData: 1,
        getTasksForMonthCached: 1,
        getAllPersonnel: 1, getSuppliers: 1, getMaterials: 1, getEquipment: 1,
        getCatalogs: 1, getPrintTemplate: 1
    },

    /** How long a cached copy may be shown before it is considered too
     *  old to draw at all. Beyond this the person waits — a figure from
     *  five minutes ago is not a reasonable thing to put on screen
     *  without saying so. */
    MAX_AGE: 180000,   // 3 minutes

    _key(action, params) {
        return action + '|' + JSON.stringify(params || []);
    },

    /**
     * wrap - the whole mechanism, around one call.
     *
     * @param action   the endpoint name
     * @param params   its arguments
     * @param fetcher  () => Promise, the real call
     * @param onFresh  (data) => void, called again if the fresh copy differs
     */
    async wrap(action, params, fetcher, onFresh) {
        if (!this.CACHEABLE[action]) return await fetcher();

        const key = this._key(action, params);
        const hit = this._mem[key];
        const fresh = hit && (Date.now() - hit.at) < this.MAX_AGE;

        if (fresh) {
            // Revalidate behind the screen. Deliberately not awaited —
            // awaiting it would reintroduce the wait this exists to
            // remove.
            this._revalidate(key, action, fetcher, onFresh, hit.json);
            return hit.data;
        }

        // Two components asking for the same thing at once — a tab and
        // its parent, say — share one request rather than racing.
        if (this._inflight[key]) return await this._inflight[key];

        const p = fetcher().then(data => {
            this._store(key, data);
            delete this._inflight[key];
            return data;
        }).catch(err => {
            delete this._inflight[key];
            throw err;
        });
        this._inflight[key] = p;
        return await p;
    },

    async _revalidate(key, action, fetcher, onFresh, oldJson) {
        if (this._inflight[key]) return;
        this._inflight[key] = true;
        try {
            const data = await fetcher();
            const json = JSON.stringify(data);
            this._store(key, data, json);
            // Redraw ONLY if something changed. Repainting identical
            // data throws away scroll position and any open row for no
            // reason, and people notice that far more than they notice
            // a stale figure.
            if (onFresh && json !== oldJson) onFresh(data);
        } catch (err) {
            // A failed background refresh is not an error the person
            // needs to see — they are looking at data that worked.
        } finally {
            delete this._inflight[key];
        }
    },

    _store(key, data, json) {
        try {
            this._mem[key] = {
                data: data,
                json: json || JSON.stringify(data),
                at: Date.now()
            };
        } catch (err) { /* unserialisable payload — simply not cached */ }
    },

    /**
     * clear - called after ANY write from this browser.
     *
     * Everything goes, not just the affected project. Working out that
     * a receipt against a PO also changes the portfolio, the cashflow
     * and the dashboard is the kind of reasoning that is correct today
     * and wrong after the next feature. Clearing everything costs one
     * uncached load and is never wrong.
     */
    clear() {
        this._mem = {};
    },

    /** Age of a cached entry in seconds, for the freshness marker. */
    ageOf(action, params) {
        const hit = this._mem[this._key(action, params)];
        return hit ? Math.round((Date.now() - hit.at) / 1000) : null;
    }
};

;

/* ═══════ js/core/busy.js ═══════ */
// ================================================================
//  core/busy.js — Every button says what it is doing. (v18)
//
//  ── THE PROBLEM ─────────────────────────────────────────────
//
//  Apps Script round trips take a second or more. A button that looks
//  identical before and after you press it tells the person nothing,
//  so they press it again — and on a Save, that is two records; on an
//  Approve, that is two approvals racing each other.
//
//  Every fix for this so far has been written by hand, per button, and
//  most buttons never got one. This makes it one call:
//
//      await Busy.run(btn, 'Saving', async () => { ... });
//
//  The label is a VERB IN PROGRESS — Save becomes Saving, Approve
//  becomes Approving. That is deliberate: a spinner says "something is
//  happening", a changed word says "your click registered and THIS is
//  what it started".
//
//  ── WHAT IT GUARANTEES ──────────────────────────────────────
//
//  The button is disabled for the whole operation, so a double click
//  cannot become a double submit — the guarantee that matters most,
//  because the others are cosmetic and this one protects the data.
//
//  The original label always comes back, including when the operation
//  throws. A button stuck on "Saving..." after a failure is worse than
//  no feedback at all: it looks like the system is still working when
//  it has already given up.
// ================================================================

const Busy = {

    /** Common labels, so the whole app phrases the same action the same
     *  way. A screen that says "Saving" in one place and "Please wait"
     *  in another reads as two different systems. */
    VERBS: {
        save: 'Saving', submit: 'Submitting', approve: 'Approving',
        reject: 'Rejecting', delete: 'Deleting', send: 'Sending',
        upload: 'Uploading', import: 'Importing', release: 'Releasing',
        pay: 'Paying', cancel: 'Cancelling', generate: 'Generating',
        create: 'Creating', add: 'Adding', update: 'Updating',
        login: 'Signing in', search: 'Searching', print: 'Preparing'
    },

    /** _verb - guesses from the button's own text, so most callers do
     *  not have to pass a label at all. */
    _verb(text) {
        const t = String(text || '').trim().toLowerCase();
        for (const k in this.VERBS) {
            if (t.indexOf(k) === 0) return this.VERBS[k];
        }
        return 'Working';
    },

    /**
     * run - the whole thing.
     *
     * @param btn    the element, or its id
     * @param label  optional; guessed from the button text when omitted
     * @param fn     the async work
     */
    async run(btn, label, fn) {
        // Called as run(btn, fn) — the label is optional and this is the
        // form most call sites will use.
        if (typeof label === 'function') { fn = label; label = null; }

        const el = typeof btn === 'string' ? document.getElementById(btn) : btn;
        if (!el) return await fn();

        // Already running. Returning rather than queueing is correct: the
        // person pressed twice meaning once.
        if (el.dataset.busy === '1') return;

        const original = el.innerHTML;
        const wasDisabled = el.disabled;
        const text = el.textContent;

        el.dataset.busy = '1';
        el.disabled = true;
        el.classList.add('is-busy');
        el.innerHTML = `<span class="busy-dot"></span>${this._esc(label || this._verb(text))}...`;

        try {
            return await fn();
        } finally {
            // ALWAYS restored, including on a throw. A button stuck on
            // "Saving..." after a failure looks like the system is still
            // working when it has already given up.
            el.dataset.busy = '';
            el.disabled = wasDisabled;
            el.classList.remove('is-busy');
            el.innerHTML = original;
        }
    },

    _esc(v) {
        return String(v == null ? '' : v)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    },

    /**
     * auto - the same thing, for a handler that was never given its
     * button.
     *
     * Almost every button in this app is wired as
     * `onclick="Page.doThing('id')"` — no `this`, so the handler has no
     * way to reach the element that was pressed. Passing it would mean
     * editing several hundred call sites twice: the markup and the
     * signature.
     *
     * Instead the last pressed button is captured on the way down (a
     * capture-phase listener runs before the inline handler), so a
     * handler can simply say what it is doing:
     *
     *     await Busy.auto('Approving', async () => { ... });
     *
     * Falls back to running the work plainly if it cannot find a button,
     * so a handler called from code rather than a click still works.
     */
    _last: null,

    async auto(label, fn) {
        if (typeof label === 'function') { fn = label; label = null; }
        return await this.run(this._last, label, fn);
    },

    /**
     * pressed - the button being clicked RIGHT NOW.
     *
     * Needed by any handler that opens a confirm dialog first: pressing
     * "Confirm" is itself a click, so by the time the dialog resolves
     * the captured button is the dialog's — which is then removed from
     * the page. Grab the real one before awaiting anything.
     */
    pressed() { return this._last; },

    /** Captured in the capture phase, which runs BEFORE the inline
     *  onclick — so by the time the handler asks, this is already set. */
    listen() {
        if (this._listening) return;
        this._listening = true;
        document.addEventListener('click', (e) => {
            const el = e.target && e.target.closest && e.target.closest('button');
            this._last = el || null;
        }, true);
    },

    /**
     * wire - retrofits every button that calls a known async action,
     * without editing each call site.
     *
     * This exists because there are several hundred buttons and editing
     * them one at a time would take longer than it is worth and would
     * miss some. Anything wired here gets the busy state for free; the
     * important paths still call Busy.run directly, because an explicit
     * label reads better than a guessed one.
     */
    wireAll(root) {
        const scope = root || document;
        scope.querySelectorAll('button[onclick]:not([data-busy-wired])').forEach(el => {
            const code = el.getAttribute('onclick') || '';
            // Only wrap handlers that look asynchronous. Wrapping a
            // synchronous toggle would make it flicker for no reason.
            if (!/\b(save|submit|approve|reject|delete|send|upload|import|release|pay|cancel|generate|create|add|update|do|run)/i.test(code)) return;
            el.dataset.busyWired = '1';
            const handler = el.onclick;
            if (!handler) return;
            el.onclick = function (ev) {
                const r = handler.call(this, ev);
                if (r && typeof r.then === 'function') {
                    Busy.run(this, () => r);
                }
                return r;
            };
        });
    }
};

;

/* ═══════ js/core/pdf-render.js ═══════ */
// ================================================================
//  core/pdf-render.js — Turning a PDF drawing into something the
//                       system can show. (v24)
//
//  ── THE PROBLEM THIS SOLVES ─────────────────────────────────
//
//  Google Drive gives no inline preview for a PDF. So a drawing
//  uploaded as a PDF showed a placeholder on the Drawings tab and could
//  not be embedded in a printed report — which is most of the value of
//  both.
//
//  Apps Script cannot render a PDF; there is no library and no service.
//  The browser can: PDF.js rasterises a page to a canvas at whatever
//  resolution you ask for, and that happens BEFORE the file is
//  uploaded, on the machine that already has the file in memory.
//
//  ── WHAT THIS IS HONESTLY NOT ───────────────────────────────
//
//  A PDF is vector. An image is not. A rendered page is sharp on screen
//  and sharp printed at A4, and it does NOT survive being zoomed
//  indefinitely the way the original does.
//
//  So the original PDF is kept and still linked. The image is a preview
//  and a print copy, not a replacement — and "Open the PDF" stays on
//  every card for the times somebody needs to read a dimension off it.
//
//  ── WHY EVERY PAGE, NOT JUST THE FIRST ──────────────────────
//
//  A drawing PDF is usually one sheet, but a set is not. Rendering only
//  page one would silently drop sheets 2 to 6 from the printed set —
//  and a set that is quietly incomplete is worse than one that is
//  obviously a PDF.
// ================================================================

const PdfRender = {

    /** PDF.js from the same CDN the rest of the app uses. Loaded on
     *  demand: most sessions never upload a PDF, and this is ~350KB. */
    CDN: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174',

    /** Render scale. 2.0 gives roughly 144 dpi against a PDF's nominal
     *  72 — sharp on a retina screen and clean printed at A4. Higher
     *  looks no better on screen and makes the upload several times
     *  larger, which matters on a site connection. */
    SCALE: 2.0,

    /** JPEG rather than PNG, at 0.92. A drawing is mostly white with
     *  thin dark lines; PNG handles that well but produces files three
     *  to five times larger, and 8 MB is the upload ceiling. At 0.92 the
     *  artefacts are not visible on a line drawing. */
    QUALITY: 0.92,

    /** Beyond this the upload becomes slow enough that people assume it
     *  has hung. A set larger than this is told to be split. */
    MAX_PAGES: 12,

    _lib: null,

    async _load() {
        if (this._lib) return this._lib;
        if (window.pdfjsLib) { this._lib = window.pdfjsLib; return this._lib; }

        await new Promise((resolve, reject) => {
            const s = document.createElement('script');
            s.src = this.CDN + '/pdf.min.js';
            s.onload = resolve;
            s.onerror = () => reject(new Error(
                'Could not load the PDF reader. Check the connection and try again, ' +
                'or upload the drawing as an image.'));
            document.head.appendChild(s);
        });

        if (!window.pdfjsLib) throw new Error('The PDF reader did not load.');
        // The worker must come from the same version, or PDF.js fails
        // with an error that says nothing useful.
        window.pdfjsLib.GlobalWorkerOptions.workerSrc = this.CDN + '/pdf.worker.min.js';
        this._lib = window.pdfjsLib;
        return this._lib;
    },

    /** isPdf - by type first, then extension. A file picked on a phone
     *  sometimes arrives with an empty type. */
    isPdf(file) {
        if (!file) return false;
        if (String(file.type || '').toLowerCase() === 'application/pdf') return true;
        return /\.pdf$/i.test(String(file.name || ''));
    },

    /**
     * render - every page of a PDF as a JPEG data URL.
     *
     * @param file      the File object
     * @param onProgress (done, total) => void, for the upload button
     * @returns { pages: [{ dataUrl, width, height }], pageCount, truncated }
     */
    async render(file, onProgress) {
        const lib = await this._load();
        const buf = await file.arrayBuffer();

        const doc = await lib.getDocument({ data: buf }).promise;
        const total = doc.numPages;
        const count = Math.min(total, this.MAX_PAGES);
        const pages = [];

        for (let n = 1; n <= count; n++) {
            const page = await doc.getPage(n);
            const viewport = page.getViewport({ scale: this.SCALE });

            const canvas = document.createElement('canvas');
            canvas.width = Math.floor(viewport.width);
            canvas.height = Math.floor(viewport.height);
            const ctx = canvas.getContext('2d');

            // A PDF page has no background of its own. Without this the
            // transparent areas render black, and a drawing comes out as
            // white lines on black.
            ctx.fillStyle = '#FFFFFF';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            await page.render({ canvasContext: ctx, viewport: viewport }).promise;

            pages.push({
                dataUrl: canvas.toDataURL('image/jpeg', this.QUALITY),
                width: canvas.width,
                height: canvas.height
            });

            // Free it immediately. A large set holds several hundred
            // megabytes of canvas otherwise, and a phone runs out.
            canvas.width = 0;
            canvas.height = 0;

            if (onProgress) onProgress(n, count);
        }

        return { pages: pages, pageCount: total, truncated: total > count };
    },

    /** base64 - the payload the upload endpoint expects, without the
     *  data-URL prefix. */
    base64(dataUrl) {
        return String(dataUrl).split(',')[1] || '';
    }
};

;

/* ═══════ js/pages/calendar.js ═══════ */
// ================================================================
//  pages/calendar.js — The month, and the work on it. (v18)
//
//  Sits at the top of the dashboard. A month grid where each day shows
//  what is due; clicking a day opens it; a Super Admin or Admin can
//  assign from there.
//
//  ── WHY A MONTH GRID AND NOT A LIST ─────────────────────────
//
//  A list answers "what is next". A month answers "when is the quiet
//  week", which is the question you ask when deciding WHEN to schedule
//  something rather than what to do now. The dashboard already has
//  several lists; it had nothing that showed shape over time.
//
//  ── THE ONE RULE ────────────────────────────────────────────
//
//  You cannot mark a task done without whatever proof was asked for.
//  The check is on the server; this is the courtesy copy so the person
//  finds out before they have typed anything.
// ================================================================

const CalendarPanel = {

    _month: null,
    _data: null,
    _selected: null,

    /** Months already fetched, kept for the tab's lifetime.
     *
     *  Stepping back and forth between two months was a full round trip
     *  each way — and people step back and forth constantly, because
     *  that is how you compare one week against another. A month you
     *  have already seen is drawn instantly and refreshed behind the
     *  screen, the same pattern FastCache uses for project data.
     */
    _months: {},
    _people: null,

    _esc(v) {
        return String(v == null ? '' : v)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    },

    _today() {
        const d = new Date();
        return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') +
               '-' + String(d.getDate()).padStart(2, '0');
    },

    async mount(el) {
        if (!el) return;
        this._month = this._month || this._today().slice(0, 7);
        el.innerHTML = '<div class="cal-shell"><div class="cal-loading">Loading the month…</div></div>';
        await this.load(el);
    },

    /**
     * load - draws from cache first when there is one, then refreshes.
     *
     * @param force  skip the cache; used after a write, where showing
     *               the old month would hide the change just made.
     */
    async load(el, force) {
        this._host = el || this._host;
        const cached = this._months[this._month];

        if (cached && !force) {
            this._data = cached;
            this._paint();
            // Behind the screen. Not awaited — awaiting it would bring
            // back the wait this exists to remove.
            this._refresh(this._month);
            return;
        }

        if (!cached) {
            // Only show a loading state when there is genuinely nothing
            // to draw. Replacing a good month with "Loading…" for half a
            // second reads as slower than leaving it alone.
            this._host.innerHTML =
                '<div class="cal-shell"><div class="cal-loading">Loading the month…</div></div>';
        }

        try {
            const d = await DataService.getTasksForMonth(this._month);
            this._months[this._month] = d;
            this._data = d;
        } catch (err) {
            this._host.innerHTML =
                `<div class="cal-shell"><div class="cal-loading">Could not load: ${this._esc(err.message)}</div></div>`;
            return;
        }
        this._paint();
    },

    async _refresh(month) {
        try {
            const d = await DataService.getTasksForMonth(month);
            const changed = JSON.stringify(d) !== JSON.stringify(this._months[month]);
            this._months[month] = d;
            // Redraw only if the month is still on screen AND something
            // actually changed — repainting an identical grid throws
            // away the open day panel for nothing.
            if (changed && this._month === month) {
                this._data = d;
                this._paint();
            }
        } catch (err) { /* a failed background refresh needs no alarm */ }
    },

    /** _prefetch - the neighbouring months, quietly.
     *
     *  Almost every use of a calendar is a step to the month either
     *  side, so both are fetched once the current one is drawn. It costs
     *  two idle requests and makes the arrows feel like they have no
     *  latency at all. */
    _prefetch() {
        // ── v25: ONE AT A TIME, AND ONLY WHEN IDLE ──
        // This fired both neighbouring months at once, on top of the
        // home payload, the current month, the notification bell and a
        // background revalidation — five or six requests from one
        // session to a backend that serialises per user. Apps Script
        // answers a POST with a one-time redirect, and under that much
        // parallelism some of them come back 404.
        //
        // A prefetch is a convenience. It must never compete with
        // something the person is waiting for.
        if (this._prefetching) return;
        const [y, m] = this._month.split('-').map(Number);
        const keys = [-1, 1].map(n => {
            const d = new Date(y, m - 1 + n, 1);
            return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
        }).filter(k => !this._months[k]);
        if (!keys.length) return;

        this._prefetching = true;
        // A second of quiet first: the dashboard's own reads have
        // finished by then, so this lands in an empty queue.
        setTimeout(async () => {
            for (const key of keys) {
                if (this._months[key]) continue;
                try {
                    this._months[key] = await DataService.getTasksForMonth(key);
                } catch (err) { /* a prefetch that fails is not an error */ }
            }
            this._prefetching = false;
        }, 1000);
    },

    async shift(n) {
        const [y, m] = this._month.split('-').map(Number);
        const d = new Date(y, m - 1 + n, 1);
        this._month = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
        this._selected = null;
        await this.load();
    },

    async goToday() {
        this._month = this._today().slice(0, 7);
        this._selected = this._today();
        await this.load();
    },

    _paint() {
        const e = this._esc.bind(this);
        const d = this._data || { tasks: [], byDay: {} };
        const today = this._today();
        // v20: a malformed month falls back to the current one rather
        // than rendering "Invalid Date". A calendar showing a broken
        // header is worse than one quietly showing today.
        if (!/^\d{4}-\d{2}$/.test(String(this._month || ''))) {
            this._month = this._today().slice(0, 7);
        }
        const [y, m] = this._month.split('-').map(Number);

        const first = new Date(y, m - 1, 1);
        const daysInMonth = new Date(y, m, 0).getDate();
        // Monday-first: a construction week starts on Monday, and a grid
        // that starts on Sunday puts the weekend in the middle of the
        // working week at a glance.
        const lead = (first.getDay() + 6) % 7;

        const user = App.getUser() || {};
        const canAssign = user.role === 'superadmin' || user.role === 'admin';

        const monthName = first.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });

        let cells = '';
        for (let i = 0; i < lead; i++) cells += '<div class="cal-day is-blank"></div>';

        for (let day = 1; day <= daysInMonth; day++) {
            const iso = `${y}-${String(m).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
            const c = d.byDay[iso] || { total: 0, open: 0, overdue: 0, mine: 0 };
            const isToday = iso === today;
            const isSel = iso === this._selected;
            const isPast = iso < today;
            const weekend = [0, 6].indexOf(new Date(y, m - 1, day).getDay()) > -1;

            // v18.2: the TITLES are written into the day, not just a
            // count. A number tells you something is there; the title
            // tells you whether it is worth opening — which is the whole
            // reason to look at a month rather than a list.
            const titles = (c.titles || []).map(t =>
                `<span class="cal-t${t.status === 'done' ? ' is-done' : ''}${t.mine ? ' is-mine' : ''}"
                       title="${e(t.title)}">${e(t.title)}</span>`).join('');
            const more = c.total > (c.titles || []).length
                ? `<span class="cal-more">+${c.total - c.titles.length} more</span>` : '';

            cells += `<button class="cal-day${isToday ? ' is-today' : ''}${isSel ? ' is-sel' : ''}${weekend ? ' is-weekend' : ''}${isPast ? ' is-past' : ''}${c.overdue ? ' has-overdue' : ''}"
                onclick="CalendarPanel.pick('${iso}')" aria-label="${iso}, ${c.total} task(s)">
                <span class="cal-top">
                    <span class="cal-n">${day}</span>
                    ${c.overdue ? `<span class="cal-pip d" title="${c.overdue} overdue"></span>` : ''}
                </span>
                ${titles}${more}
                ${c.total ? `<span class="cal-cnt${c.mine ? ' is-mine' : ''}">${c.total}</span>` : ''}
            </button>`;
        }

        const sel = this._selected;
        const dayTasks = sel ? d.tasks.filter(t => t.dueDate === sel) : [];

        this._host.innerHTML = `
        <div class="cal-shell">
            <div class="cal-head">
                <button class="cal-nav" onclick="CalendarPanel.shift(-1)" aria-label="Previous month">‹</button>
                <b>${e(monthName)}</b>
                <button class="cal-nav" onclick="CalendarPanel.shift(1)" aria-label="Next month">›</button>
                <button class="cal-today" onclick="CalendarPanel.goToday()">Today</button>
                <span class="cal-legend">
                    <span><i class="cal-pip d"></i>overdue</span>
                    <span><i class="cal-pip a"></i>open</span>
                    <span><i class="cal-pip g"></i>done</span>
                </span>
                ${canAssign ? `<button class="btn-sm primary cal-add"
                    onclick="CalendarPanel.openNew('${sel || today}')">+ Assign a task</button>` : ''}
            </div>

            ${this._mineHtml()}

            <div class="cal-dow">
                ${['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
                    .map(x => `<span>${x}</span>`).join('')}
            </div>
            <div class="cal-grid">${cells}</div>

            ${sel ? `<div class="cal-day-panel">
                <div class="cdp-head">
                    <b>${e(new Date(sel + 'T00:00:00').toLocaleDateString('en-US',
                        { weekday: 'long', day: 'numeric', month: 'long' }))}</b>
                    <span class="muted">${dayTasks.length} task${dayTasks.length === 1 ? '' : 's'}</span>
                    ${canAssign ? `<button class="btn-sm" onclick="CalendarPanel.openNew('${sel}')">+ Assign</button>` : ''}
                    <button class="btn-sm" onclick="CalendarPanel.pick('')">Close</button>
                </div>
                ${dayTasks.length ? dayTasks.map(t => this._task(t)).join('')
                    : '<div class="cdp-empty">Nothing due on this day.</div>'}
            </div>` : ''}
        </div>`;

        // Neighbouring months, once the current one is on screen.
        this._prefetch();
    },

    /**
     * _mineHtml (v18.1) - YOUR tasks, above the grid.
     *
     * The grid answers "when is the quiet week". It does not answer
     * "what have I been given", and that is the question the person
     * assigned a task has the moment they log in. Without this they
     * would have to hunt for the right day, which means they would
     * simply rely on the email — and a task nobody can find in the
     * system is a task the system is not managing.
     *
     * Overdue first, then due today, then the rest. Only open ones:
     * a finished task is not something you still have to do.
     */
    _mineHtml() {
        const d = this._data || { tasks: [] };
        const today = this._today();
        const mine = (d.tasks || [])
            .filter(t => t.isMine && t.status === 'open')
            .sort((a, b) => a.dueDate < b.dueDate ? -1 : 1);

        if (!mine.length) return '';

        const e = this._esc.bind(this);
        const overdue = mine.filter(t => t.dueDate < today).length;
        const due = mine.filter(t => t.dueDate === today).length;

        return `<div class="cal-mine${overdue ? ' has-overdue' : ''}">
            <div class="cm-head">
                ${Icon.check({ size: 13 })}
                <b>Assigned to you</b>
                <span>${mine.length} open${overdue ? ` · <b class="od">${overdue} overdue</b>` : ''}${due ? ` · ${due} due today` : ''}</span>
            </div>
            <div class="cm-list">
                ${mine.slice(0, 6).map(t => {
                    const late = t.dueDate < today;
                    const now = t.dueDate === today;
                    return `<button class="cm-item${late ? ' is-late' : ''}${now ? ' is-today' : ''}"
                        onclick="CalendarPanel.jumpTo('${e(t.dueDate)}')">
                        <span class="cm-when">${late ? 'overdue' : now ? 'today' : e(t.dueDate.slice(5))}</span>
                        <span class="cm-title">${e(t.title)}</span>
                        ${t.proofRequired !== 'none' ? '<span class="cm-flag">proof</span>' : ''}
                        ${t.priority === 'high' ? '<span class="cm-flag hi">high</span>' : ''}
                    </button>`;
                }).join('')}
                ${mine.length > 6 ? `<div class="cm-more">and ${mine.length - 6} more this month</div>` : ''}
            </div>
        </div>`;
    },

    /** jumpTo - opens the day a task is due, from the "assigned to you"
     *  strip. Selecting the day rather than opening the task directly
     *  keeps one way of acting on a task instead of two. */
    jumpTo(iso) {
        if (iso.slice(0, 7) !== this._month) {
            this._month = iso.slice(0, 7);
            this._selected = iso;
            this.load();
            return;
        }
        this._selected = iso;
        this._paint();
        document.querySelector('.cal-day-panel')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    },

    _task(t) {
        const e = this._esc.bind(this);
        const done = t.status === 'done';
        const cancelled = t.status === 'cancelled';
        const overdue = !done && !cancelled && t.dueDate < this._today();
        const user = App.getUser() || {};
        const canManage = user.role === 'superadmin' || user.role === 'admin';

        return `<div class="cdp-task${done ? ' is-done' : ''}${cancelled ? ' is-cancelled' : ''}${overdue ? ' is-overdue' : ''}${t.priority === 'high' ? ' is-high' : ''}">
            <div class="cdp-main">
                <div class="cdp-title">
                    ${done ? Icon.check({ size: 12 }) : ''}${e(t.title)}
                    ${t.priority === 'high' && !done ? '<span class="cdp-flag">high</span>' : ''}
                    ${t.proofRequired !== 'none' && !done
                        ? `<span class="cdp-flag proof">${t.proofRequired === 'file' ? 'photo required' : 'note required'}</span>` : ''}
                </div>
                ${t.detail ? `<p class="cdp-detail">${e(t.detail)}</p>` : ''}
                <div class="cdp-meta">
                    ${t.isMine ? '<b>You</b>' : e(t.assignedToName)}
                    · assigned by ${e(t.assignedByName)}
                    ${t.projectId ? ' · ' + e(t.projectId) : ''}
                    ${overdue ? ' · <b class="od">overdue</b>' : ''}
                </div>

                ${done ? `<div class="cdp-proof">
                    Completed by ${e(t.completedByName)}${t.completedAt ? ' · ' + e(String(t.completedAt).slice(0, 10)) : ''}
                    ${t.proofNote ? `<p>${e(t.proofNote)}</p>` : ''}
                    ${t.proofUrl ? `<a href="${e(t.proofUrl)}" target="_blank" rel="noopener">View proof</a>` : ''}
                </div>` : ''}
                ${t.reopenedAt ? `<div class="cdp-reopen">Reopened — the completion above is kept as a record.</div>` : ''}
            </div>

            <div class="cdp-actions">
                ${!done && !cancelled && t.canComplete
                    ? `<button class="btn-sm primary" onclick="CalendarPanel.openComplete('${e(t.id)}')">Mark done</button>` : ''}
                ${done && canManage
                    ? `<button class="btn-sm" onclick="CalendarPanel.reopen('${e(t.id)}')">Reopen</button>` : ''}
                ${!done && !cancelled && canManage
                    ? `<button class="btn-sm danger" onclick="CalendarPanel.cancel('${e(t.id)}')">Cancel</button>` : ''}
            </div>
        </div>`;
    },

    pick(iso) {
        this._selected = iso || null;
        this._paint();
    },

    // ─── assigning ───────────────────────────────────────────

    async openNew(iso) {
        const e = this._esc.bind(this);
        // v18.1: its own endpoint. This read getHomeData().users, which
        // does not exist — so the picker was empty and nothing could be
        // assigned to anybody. Cached for the session: the user list
        // changes about once a quarter.
        if (!this._people) {
            try {
                this._people = await DataService.getAssignableUsers();
            } catch (err) { this._people = []; }
        }
        const people = this._people;

        document.getElementById('taskModal')?.remove();
        const m = document.createElement('div');
        m.className = 'print-modal-overlay open';
        m.id = 'taskModal';
        m.innerHTML = `
            <div class="print-modal-content" style="max-width:520px;">
                <button class="close-modal" onclick="document.getElementById('taskModal').remove()">${Icon.close({ size: 18 })}</button>
                <div class="print-header"><h2>Assign a task</h2>
                    <div class="print-meta">The person is notified straight away</div></div>

                <div class="field"><label>What needs doing *</label>
                    <input type="text" id="tk-title" maxlength="200"
                        placeholder="e.g. Chase AgriFarms on PB-02" /></div>

                <div class="field"><label>Detail</label>
                    <textarea id="tk-detail" rows="2"
                        placeholder="Anything the person needs to know to do it"></textarea></div>

                <div class="db-form-grid">
                    <div class="field"><label>Who *</label>
                        <select id="tk-to">
                            <option value="">Select a person...</option>
                            ${people.map(p =>
                                `<option value="${e(p.email)}">${e(p.name)}${p.role ? ' · ' + e(p.role) : ''}</option>`).join('')}
                        </select></div>
                    <div class="field"><label>Due *</label>
                        <input type="date" id="tk-due" value="${e(iso)}" /></div>
                </div>

                <div class="db-form-grid">
                    <div class="field"><label>Priority</label>
                        <select id="tk-pri">
                            <option value="normal">Normal</option>
                            <option value="high">High</option>
                            <option value="low">Low</option>
                        </select></div>
                    <div class="field"><label>Proof of completion</label>
                        <select id="tk-proof">
                            <option value="none">Not required</option>
                            <option value="note">A note saying what was done</option>
                            <option value="file">A photo or file</option>
                        </select></div>
                </div>

                <div class="pr-budget-box" style="margin-top:10px;">
                    <b>About proof</b>
                    <p>Decide now, while you know whether it matters. When proof is required the task
                    cannot be marked done without it — and the proof stays attached even if the task
                    is later reopened.</p>
                </div>

                <div class="print-actions">
                    <button class="btn-primary" id="tk-go" onclick="CalendarPanel.create(this)">Assign</button>
                    <button class="btn-ghost" onclick="document.getElementById('taskModal').remove()">Cancel</button>
                </div>
            </div>`;
        document.body.appendChild(m);
        setTimeout(() => document.getElementById('tk-title')?.focus(), 60);
    },

    async create(btn) {
        const v = id => (document.getElementById(id)?.value || '').trim();
        if (!v('tk-title')) { UI.toast('Give the task a title.', 'error'); return; }
        if (!v('tk-to')) { UI.toast('Choose who it is for.', 'error'); return; }
        if (!v('tk-due')) { UI.toast('Pick a due date.', 'error'); return; }

        await Busy.run(btn, 'Assigning', async () => {
            try {
                await DataService.createTask({
                    title: v('tk-title'), detail: v('tk-detail'),
                    assignedTo: v('tk-to'), dueDate: v('tk-due'),
                    priority: v('tk-pri'), proofRequired: v('tk-proof')
                });
                // ── v20 FIX: READ THE FIELDS BEFORE REMOVING THE MODAL ──
                // The due date was read on the two lines AFTER the modal
                // was removed from the DOM — so getElementById returned
                // null, v() fell back to '', and _month became an empty
                // string. _paint then did ''.split('-') and built
                // `new Date(NaN, NaN, 1)`, which renders as "Invalid
                // Date" until Today is pressed and resets it.
                //
                // Everything needed is captured while the modal still
                // exists.
                const due = v('tk-due');
                document.getElementById('taskModal')?.remove();
                UI.toast('Task assigned.', 'success');
                this._selected = due;
                this._month = due.slice(0, 7);
                delete this._months[this._month];
                await this.load(null, true);
            } catch (err) { UI.toast('' + err.message, 'error'); }
        });
    },

    // ─── completing ──────────────────────────────────────────

    openComplete(id) {
        const t = (this._data.tasks || []).find(x => x.id === id);
        if (!t) return;
        const e = this._esc.bind(this);
        const need = t.proofRequired;

        document.getElementById('doneModal')?.remove();
        const m = document.createElement('div');
        m.className = 'print-modal-overlay open';
        m.id = 'doneModal';
        m.innerHTML = `
            <div class="print-modal-content" style="max-width:460px;">
                <button class="close-modal" onclick="document.getElementById('doneModal').remove()">${Icon.close({ size: 18 })}</button>
                <div class="print-header"><h2>Mark done</h2>
                    <div class="print-meta">${e(t.title)}</div></div>

                ${need !== 'none' ? `<div class="pr-budget-box near">
                    <b>${need === 'file' ? 'A photo or file is required' : 'A note is required'}</b>
                    <p>This was set when the task was assigned. It cannot be completed without it.</p>
                </div>` : ''}

                <div class="field"><label>What was done${need === 'note' ? ' *' : ''}</label>
                    <textarea id="dn-note" rows="3"
                        placeholder="e.g. Called Ms Reyes, payment promised by Friday"></textarea></div>

                <div class="field"><label>Photo or file${need === 'file' ? ' *' : ''}</label>
                    <div class="file-drop"><input type="file" id="dn-file" /></div></div>

                <div class="print-actions">
                    <button class="btn-primary" onclick="CalendarPanel.complete('${e(id)}', this)">Mark done</button>
                    <button class="btn-ghost" onclick="document.getElementById('doneModal').remove()">Cancel</button>
                </div>
            </div>`;
        document.body.appendChild(m);
    },

    async complete(id, btn) {
        const note = (document.getElementById('dn-note')?.value || '').trim();
        const file = document.getElementById('dn-file')?.files?.[0];

        await Busy.run(btn, 'Saving', async () => {
            try {
                const proof = { note: note };
                if (file) {
                    proof.fileBase64 = await fileToBase64_(file);
                    proof.fileName = file.name;
                    proof.fileMime = file.type;
                }
                await DataService.completeTask(id, proof);
                document.getElementById('doneModal')?.remove();
                UI.toast('Marked done.', 'success');
                delete this._months[this._month];
                await this.load(null, true);
            } catch (err) { UI.toast('' + err.message, 'error'); }
        });
    },

    async reopen(id) {
        const ok = await Confirm.open('Reopen this task?',
            'The completion and any proof are kept — the record will show both attempts.');
        if (!ok) return;
        try {
            await DataService.reopenTask(id, '');
            UI.toast('Reopened.', 'success');
            delete this._months[this._month];
            await this.load(null, true);
        } catch (err) { UI.toast('' + err.message, 'error'); }
    },

    async cancel(id) {
        const ok = await Confirm.open('Cancel this task?',
            'It stays on the calendar marked cancelled, so the person it was assigned to can see ' +
            'what happened to it rather than finding it gone.');
        if (!ok) return;
        try {
            await DataService.cancelTask(id, '');
            UI.toast('Cancelled.', 'success');
            delete this._months[this._month];
            await this.load(null, true);
        } catch (err) { UI.toast('' + err.message, 'error'); }
    }
};

;

/* ═══════ js/services/data-service.js ═══════ */
// ================================================================
//  services/data-service.js — fetch() bridge to the Apps Script API
//
//  PURPOSE: The ONLY place the frontend talks to the backend.
//  Every method wraps gasCall(action, ...params), which POSTs
//  { action, params, userEmail } to GAS_API_URL and unwraps the
//  { success, data | error } envelope (see backend/02-Api.gs).
//
//  DEPLOYMENT: replace GAS_API_URL with your Web App URL (ends in
//  /exec) after each new Apps Script deployment.
//
//  SCALABILITY: to consume a new backend action, add one async
//  wrapper method here — pages never call fetch() directly.
// ================================================================

// v12: the URL lives in js/core/config.js — the one file that differs
// between companies. Hardcoding it here is what would force a fork of
// the whole repository to stand up a second company.
//
// The fallback is deliberate and loud: an empty string would fail with
// an unhelpful network error, so a missing config says what is wrong.
const GAS_API_URL = (typeof CONFIG !== 'undefined' && CONFIG.apiUrl)
    ? CONFIG.apiUrl
    : (function () {
        console.error('js/core/config.js is missing or has no apiUrl — the app cannot reach its backend.');
        return '';
    })();

/**
 * getCurrentUserEmail - Retrieves the current user's email from localStorage
 * PURPOSE: Passes the authenticated user's email to the backend for authorization
 */
function getCurrentUserEmail() {
    try {
        const stored = localStorage.getItem('fctc_user');
        if (stored) return JSON.parse(stored).email || '';
    } catch (e) {}
    return '';
}

/**
 * v7.0 SESSION TOKEN
 * The browser no longer tells the server who it is — it presents an
 * opaque token the server issued at login, and the server decides the
 * identity. The stored email is kept only for display.
 */
function getSessionToken() {
    try { return localStorage.getItem('fctc_token') || ''; } catch (e) { return ''; }
}
function setSessionToken(token) {
    try {
        if (token) localStorage.setItem('fctc_token', token);
        else localStorage.removeItem('fctc_token');
    } catch (e) {}
}

/**
 * handleSessionExpired - Sliding 8-hour window means this only fires
 * after real inactivity. Warn about unsaved work BEFORE clearing, so a
 * half-finished daily report isn't silently lost.
 */
function handleSessionExpired() {
    if (window.__fctcExpiring) return;
    window.__fctcExpiring = true;
    const hasDraft = !!document.querySelector('#dailyAddForm.open, #transferModal, #editorsModal');
    setSessionToken('');
    try { localStorage.removeItem('fctc_user'); } catch (e) {}
    const msg = hasDraft
        ? 'Your session expired after 8 hours of inactivity. You have an open form - please copy any unsaved work before continuing, as you will be returned to the login page.'
        : 'Your session expired after 8 hours of inactivity. Please log in again to continue.';
    setTimeout(() => { alert(msg); window.location.reload(); }, 50);
}

/**
 * gasCall - Generic API caller
 * PURPOSE: Sends requests to the backend with proper authentication
 */
/**
 * gasCall - every request goes through here.
 *
 * v17: the cache is wired in at this ONE point, so it covers every
 * endpoint without a single page knowing it exists. That is the same
 * property that makes a future database migration a rewrite of this
 * function rather than of the whole app.
 */
async function gasCall(action) {
    const params = Array.prototype.slice.call(arguments, 1);

    // ── v17: WRITES CLEAR THE CACHE, ALWAYS ──
    // Seeing your own change missing is the failure people notice and
    // lose trust over, so it is prevented at the source rather than
    // patched per page.
    if (typeof FastCache !== 'undefined' && !FastCache.CACHEABLE[action]) {
        FastCache.clear();
    }

    return _gasCallRaw(action, params);
}

/**
 * READ_ONLY_RE (v25) - which actions are safe to send twice.
 *
 * ── THE DISTINCTION THIS FILE TURNS ON ──────────────────────
 *
 * Apps Script answers a POST with a redirect carrying a one-time token,
 * and under concurrency that redirect sometimes 404s. The request may
 * have been received and executed before the answer was lost.
 *
 * So retrying a READ costs a second query. Retrying a WRITE can BILL
 * THE CLIENT TWICE, release the same cash advance twice, or approve
 * something twice — and nothing in the log would show it as anything
 * other than two deliberate actions.
 *
 * A read that fails is a message on screen. A duplicated write is money
 * moved. Only reads are retried, and the pattern is deliberately the
 * conservative one: anything that is not obviously a read is treated as
 * a write.
 */
const READ_ONLY_RE = /^(get|list|search|preview|export|find|check|is|has|whoAmI|duplicatePreview|audit)/i;

function isRetryable_(action) {
    return READ_ONLY_RE.test(String(action || ''));
}

async function _gasCallRaw(action, params) {
    const payload = {
        action: action,
        params: params,
        token: getSessionToken(),        // v7.0: identity proof
        userEmail: getCurrentUserEmail() // display only; server ignores it
    };

    // v25: queued, so a handful of parallel reads cannot stampede the
    // backend into the redirect failure that produces "Network error:
    // 404".
    return RequestQueue.run(
        () => _gasFetch_(payload),
        { retry: isRetryable_(action) }
    );
}

async function _gasFetch_(payload) {
    const response = await fetch(GAS_API_URL, {
        method: 'POST',
        body: JSON.stringify(payload)
    });

    if (!response.ok) {
        const err = new Error(response.status === 404
            // A plain "404" reads as a coding fault and sends people
            // looking in the wrong place. This is almost always Apps
            // Script's redirect failing under load.
            ? 'The server did not answer (404). This is usually temporary — retrying.'
            : 'Network error: ' + response.status);
        // Carried so the queue can decide whether it is worth retrying.
        err.httpStatus = response.status;
        throw err;
    }

    const result = await response.json();
    if (!result.success) {
        if (result.code === 'SESSION_EXPIRED') {
            handleSessionExpired();
            throw new Error('Session expired. Please log in again.');
        }
        throw new Error(result.error || 'Unknown server error');
    }
    return result.data;
}

